    body: 'أرسل الخليفة عثمان بن عفان رضي الله عنه وفدًا رسميًا إلى إمبراطور أسرة تانغ في الصين عام 651م، أي بعد وفاة النبي ﷺ بنحو 19 سنة فقط.',
    explanation: 'بُنيت مساجد مبكرة في كانتون وتشانغآن، ولا يزال مسجد هوايشينغ في غوانغتشو شاهدًا على وجود الجالية المسلمة المبكرة في الصين عبر التجارة والدبلوماسية.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%A5%D8%B3%D9%84%D8%A7%D9%85_%D9%81%D9%8A_%D8%A7%D9%84%D8%B5%D9%8A%D9%86',
  ),
  Fact(
    id: 22,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الصحابي اللي اشترى البئر ووقفه للناس فبقى أغنى متصدق',
    body: 'عندما هاجر المسلمون للمدينة لم يكن فيها ماء عذب متاح بسهولة غير «بئر رومة» التي كان يملكها رجل ويبيع ماءها، فاشتراها عثمان بن عفان وجعلها صدقة للجميع.',
    explanation: 'المثير إن البئر وأرض النخيل حولها لا تزال موقوفة حتى يومنا هذا في المدينة المنورة وتُصرف عوائدها في أعمال الخير وتطوير الوقف.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A8%D8%A6%D8%B1_%D8%B1%D9%88%D9%85%D8%A9',
  ),
  Fact(
    id: 23,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الإمام البخاري لم يكن عربيًا بل وُلد في أوزبكستان الحالية',
    body: 'الإمام محمد بن إسماعيل البخاري، جامع أصح كتاب في الحديث النبوي، وُلد عام 194هـ في مدينة بخارى في آسيا الوسطى (أوزبكستان حاليًا).',
    explanation: 'ده بيورينا قد إيه الحضارة الإسلامية كانت عالمية؛ علماء من فارس وآسيا الوسطى والأندلس والشام ومصر خدموا اللغة العربية والسنة النبوية بنفس الشغف.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D9%85%D8%AF_%D8%A8%D9%86_%D8%A5%D8%B3%D9%85%D8%A7%D8%B9%D9%8A%D9%84_%D8%A7%D9%84%D8%A8%D8%AE%D8%A7%D8%B1%D9%8A',
  ),
  Fact(
    id: 24,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'حجر رشيد في البداية لم يكن أثرًا منسيًا عند العلماء المسلمين',
    body: 'قبل قرون من فك شامبليون لرموز الهيروغليفية، استطاع العالم المسلم ابن وحشية النبطي في القرن العاشر ترجمة جزء كبير من الرموز الهيروغليفية في كتابه «شوق المستهام».',
    explanation: 'ابن وحشية لاحظ إن بعض العلامات الهيروغليفية بتعبر عن أصوات مش مجرد رسومات، وكتابه تُرجم للإنجليزية قبل اكتشاف شامبليون بـ 16 سنة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D8%A8%D9%86_%D9%88%D8%AD%D8%B4%D9%8A%D8%A9_%D8%A7%D9%84%D9%86%D8%A8%D8%B7%D9%8A',
  ),
  Fact(
    id: 25,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'مكتبة بغداد في بيت الحكمة كانت بتوزن الكتب المترجمة بالذهب',
    body: 'بلغ شغف العباسيين بالعلم ذروته في عهد المأمون لدرجة إنه كان يكافئ المترجمين الكبار مثل حنين بن إسحاق بوزن الكتاب المترجم ذهبًا.',
    explanation: 'سياسة الترجمة المنظمة في بيت الحكمة أنقذت علوم اليونان والفرس والهند من الضياع، ومهدت لنهضة علمية استمرت قرونًا.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A8%D9%8A%D8%AA_%D8%A7%D9%84%D8%AD%D9%83%D9%85%D8%A9',
  ),
  Fact(
    id: 26,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أكثر سورة في القرآن فيها ذكر لفظ الجلالة في كل آية',
    body: 'سورة المجادلة هي السورة الوحيدة التي ورد فيها لفظ الجلالة «الله» في كل آية من آياتها الـ 22.',
    explanation: 'التركيز ده في السورة بيرسّخ رقابة الله وعلمه بكل نجوى سرية أو علنية، وبدأتها بقصة المرأة اللي اشتكت زوجها للنبي ﷺ فسمع الله شكواها من فوق سبع سماوات.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D9%85%D8%AC%D8%A7%D8%AF%D9%84%D8%A9',
  ),
  Fact(
    id: 27,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'إدارة البريد السريع كانت سر قوة الدولة العباسية',
    body: 'امتلكت الدولة الأموية ثم العباسية شبكة بريد منظمة جدًا تُسمى «ديوان البريد» لنقل الأخبار والمراسيم عبر محطات خيل وجمال متتابعة.',
    explanation: 'النظام ده مكنّ الخليفة في بغداد يعرف أخبار الأقاليم البعيدة في أيام معدودة، وكان رئيس البريد بمثابة عين الدولة على الولاة لمنع ظلمهم.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%A8%D8%B1%D9%8A%D8%AF_%D9%81%D9%8A_%D8%A7%D9%84%D8%AF%D9%88%D9%84%D8%A9_%D8%A7%D9%84%D8%A5%D8%B3%D9%84%D8%A7%D9%85%D9%8A%D8%A9',
  ),
  Fact(
    id: 28,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'شخص أسس أوقافًا للقطط الضالة وللحيوانات العجوز في دمشق',
    body: 'عرف التاريخ الإسلامي نظام «أوقاف الحيوانات»، ومنها أوقاف في دمشق والقاهرة لإطعام القطط والكلاب الضالة ورعاية الخيول المسنة بعد توقفها عن العمل.',
    explanation: 'الفكرة نابعة من حديث «في كل كبد رطبة أجر»، وتحوّلت لمؤسسات مالية مستقلة لها أراضٍ ومزارع يُصرف ريعها على الرفق بالحيوان قبل قرون من ظهور جمعيات الرفق الحديثة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%88%D9%82%D9%81_%D9%81%D9%8A_%D8%A7%D9%84%D8%A5%D8%B3%D9%84%D8%A7%D9%85',
  ),
  Fact(
    id: 29,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سورة قصيرة جدًا نُزلت لتسلية النبي ﷺ لكنها تحمل 3 نعم عظيمة',
    body: 'سورة الكوثر تتكون من 3 آيات و10 كلمات فقط، لكنها جمعت للرسول ﷺ ثلاث بشريات كبرى وقت حزنه على فقدان أبنائه.',
    explanation: 'عندما عيّره المشركون بقولهم «أبتر» أي مقطوع الذكر، نزلت السورة تمنحه الكوثر (الخير الكثير والنهر في الجنة)، وتوصيه بالصلاة والنحر، وتؤكد أن مبغضيه هم المنقطعون.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D9%83%D9%88%D8%AB%D8%B1',
  ),
  Fact(
    id: 30,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الجامع الأزهر كان اسمه في البداية جامع القاهرة',
    body: 'عندما بنى جوهر الصقلي الجامع الأزهر عام 970م، كان اسمه «جامع القاهرة» ثم سُمي الأزهر نسبةً إلى السيدة فاطمة الزهراء.',
    explanation: 'بدأ الجامع للصلاة والدعوة الفاطمية، وبعدين تحوّل في العهد الأيوبي والمملوكي لأكبر منارة علمية لأهل السنة في العالم الإسلامي لأكثر من ألف سنة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%AC%D8%A7%D9%85%D8%B9_%D8%A7%D9%84%D8%A3%D8%B2%D9%87%D8%B1',
  ),
  Fact(
    id: 31,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول غزوة بحرية إسلامية قادتها سيدة مع زوجها',
    body: 'انطلق الأسطول الإسلامي الأول في البحر المتوسط عام 28هـ في عهد عثمان بن عفان لفتح قبرص، وشاركت فيه الصحابية أم حرام بنت ملحان.',
    explanation: 'النبي ﷺ بشّرها قبل وفاته بسنوات إنها هتكون من أول من يركبون البحر في سبيل الله، وبالفعل ركبت السفينة في عهد عثمان وتوفيت ودُفنت في قبرص.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D9%85_%D8%AD%D8%B1%D8%A7%D9%85_%D8%A8%D9%86%D8%AA_%D9%85%D9%84%D8%AD%D8%A7%D9%86',
  ),
  Fact(
    id: 32,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا استمرت غزوة الخندق دون قتال جيشين وجهًا لوجه؟',
    body: 'في غزوة الأحزاب (الخندق)، استطاع حفر الخندق — الذي اقترحه سلمان الفارسي — شلّ حركة 10 آلاف مقاتل من الأحزاب لأكثر من 3 أسابيع.',
    explanation: 'تكتيك الخندق لم يكن معروفًا في حروب العرب وقتها، ففاجأ قريش وأحلافها ومنعهم من الاقتحام، ومع الرياح الشديدة وتفكيك التحالف انسحبوا دون معركة شاملة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%BA%D8%B2%D9%88%D8%A9_%D8%A7%D9%84%D8%AE%D9%86%D8%AF%D9%82',
  ),
  Fact(
    id: 33,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول مؤلف عربي وضع علم الاجتماع وفلسفة التاريخ',
    body: 'أسس عبد الرحمن بن خلدون في القرن الرابع عشر علم «العمران البشري» في مقدمته الشهيرة، ويُعد مؤسس علم الاجتماع الحديث.',
    explanation: 'ابن خلدون حلّل أسباب صعود الدول وسقوطها وربط بين الاقتصاد والضرائب والعصبية وحالة المجتمع، وأفكاره لسه بتتدرس في كبرى الجامعات العالمية.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D8%A8%D9%86_%D8%AE%D9%84%D8%AF%D9%88%D9%86',
  ),
  Fact(
    id: 34,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'قرطبة في القرن العاشر كانت منارة أوروبا المضاءة',
    body: 'في وقت كانت فيه مدن أوروبا غارقة في الظلام ليلًا، كانت شوارع قرطبة في الأندلس مرصوفة ومضاءة بالمصابيح لمسافات طويلة وتضم مئات الحمامات والمكتبات.',
    explanation: 'وصل عدد كتب مكتبة الحكم المستنصر في قرطبة لنحو 400 ألف مجلد، وكانت مقصدًا للطلاب من كل أنحاء أوروبا لطلب العلم.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%82%D8%B1%D8%B7%D8%A8%D8%A9_(%D8%A7%D9%84%D8%AE%D9%84%D8%A7%D9%81%D8%A9_%D8%A7%D9%84%D8%A3%D9%85%D9%88%D9%8A%D8%A9)',
  ),
  Fact(
    id: 35,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أكبر متبرع في التاريخ المسجل كان ملك مالي المسلم منسى موسى',
    body: 'خلال رحلته للحج عام 1324م، أنفق ملك مالي المسلم منسى موسى من الذهب في القاهرة والمدينة كميات ضخمة تسببت في انخفاض سعر الذهب في مصر لسنوات.',
    explanation: 'كان مع منسى موسى قافلة فيها آلاف المرافقين والجمال المحملة بالذهب، وأنشأ في تمبكتو مساجد ومدارس وجعلها مركزًا علميًا كبيرًا في غرب إفريقيا.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D9%86%D8%B3%D9%89_%D9%85%D9%88%D8%B3%D9%89',
  ),
  Fact(
    id: 36,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الشخص الذي جمع الناس على مصحف واحد لم يكن أبا بكر بل عثمان',
    body: 'أبو بكر الصديق أمر بجمع القرآن لأول مرة في صحف واحدة بعد معركة اليمامة، بينما عثمان بن عفان نسخ منه مصاحف موحدة وزعها على الأمصار.',
    explanation: 'الفرق إن جمع أبي بكر كان لحفظ القرآن من الضياع بوفاة القراء، أما جمع عثمان فكان لتوحيد الرسم والكتابة بعد اختلاف اللهجات في البلدان المفتوحة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AC%D9%85%D8%B9_%D8%A7%D9%84%D9%82%D8%B1%D8%A2%D9%86',
  ),
  Fact(
    id: 37,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول مؤذن في الإسلام أذّن في السماء وليس على الأرض فقط',
    body: 'بلال بن رباح لم يكن فقط أول مؤذن في الإسلام، بل صعد فوق سطح الكعبة ليؤذن يوم فتح مكة في مشهد أعلن المساواة الكاملة بين البشر.',
    explanation: 'اختيار بلال — الذي كان عبدًا يُعذَّب في مكة — ليقف فوق أشرف بقعة ويعلن التوحيد كان رسالة عملية على إن الإسلام يقيس الناس بالتقوى لا بالأنساب.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A8%D9%84%D8%A7%D9%84_%D8%A8%D9%86_%D8%B1%D8%A8%D8%A7%D8%AD',
  ),
  Fact(
    id: 38,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'صاحب لقب «أمين هذه الأمة» رفض الإمارة وتولى جيش الشام بالزهد',
    body: 'أبو عبيدة عامر بن الجراح هو الصحابي الذي خصّه النبي ﷺ بلقب «أمين هذه الأمة»، وكان يعيش في بيت بسيط حتى وهو قائد جيوش الشام.',
    explanation: 'لما زاره عمر بن الخطاب في الشام لم يجد في بيته إلا سيفه وترسه ورحله، فبكى عمر وقال: كلنا غيّرتنا الدنيا إلا أنت يا أبا عبيدة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%A8%D9%88_%D8%B9%D8%A8%D9%8A%D8%AF%D8%A9_%D8%A8%D9%86_%D8%A7%D9%84%D8%AC%D8%B1%D8%A7%D8%AD',
  ),
  Fact(
    id: 39,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'وثيقة المدينة المنورة سبقت الدساتير المدنية الحديثة بقرون',
    body: 'كتب النبي ﷺ فور وصوله للمدينة «صحيفة المدينة»، وهي وثيقة دستورية نظّمت الحقوق والواجبات بين المهاجرين والأنصار واليهود في دولة واحدة.',
    explanation: 'الوثيقة أكدت حرية العقيدة وحماية الجار والإنفاق المشترك للدفاع عن المدينة ومحاسبة المجرم بشخصه لا بقبيلته.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B5%D8%AD%D9%8A%D9%81%D8%A9_%D8%A7%D9%84%D9%85%D8%AF%D9%8A%D9%86%D8%A9',
  ),
  Fact(
    id: 40,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الآية التي نزلت داخل جوف الكعبة في فتح مكة',
    body: 'حين دخل النبي ﷺ الكعبة يوم فتح مكة ومعه مفتاحها، أمره الله عز وجل أن يرد الأمانات إلى أهلها فسلّم المفتاح للصحابي عثمان بن طلحة.',
    explanation: 'نزلت آية «إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا»، ولا يزال أحفاد بني شيبة (آل عثمان بن طلحة) يحتفظون بسدانة الكعبة حتى اليوم.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D8%AF%D8%A7%D9%86%D8%A9_%D8%A7%D9%84%D9%83%D8%B9%D8%A8%D8%A9',
  ),
  Fact(
    id: 41,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'نظام السفتجة في التجارة الإسلامية هو جدّ الشيك البنكي',
    body: 'ابتكر التجار المسلمون في العصر العباسي نظام «السفتجة» و«الصك»، وهما ورقة مالية تُودَع مقابلها النقود في مدينة وتُصرف في مدينة أخرى بأمان.',
    explanation: 'من كلمة «صك» العربية اشتُقت الكلمة الإنجليزية Cheque (شيك)، واستخدمه التجار لتفادي مخاطر حمل الذهب في طرق القوافل الطويلة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%81%D8%AA%D8%AC%D8%A9',
  ),
  Fact(
    id: 42,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أكثر مدينة إسلامية في عدد السكان المسلمين في العالم ليست عربية',
    body: 'تضم إندونيسيا وحدها أكبر عدد من المسلمين في دولة واحدة (أكثر من 230 مليون مسلم)، تليها باكستان والهند وبنغلاديش.',
    explanation: 'انتشر الإسلام في إندونيسيا سلميًا عبر التجار المسلمين والدعاة والأخلاق الحسنة في التعامل التجاري دون فتوحات عسكرية.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%A5%D8%B3%D9%84%D8%A7%D9%85_%D9%81%D9%8A_%D8%A5%D9%86%D8%AF%D9%88%D9%86%D9%8A%D8%B3%D9%8A%D8%A7',
  ),
  Fact(
    id: 43,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أم المؤمنين أم سلمة أنقذت الموقف في صلح الحديبية بمشورتها',
    body: 'عندما تردد بعض الصحابة في التحلل من الإحرام بعد صلح الحديبية حزنًا على عدم دخول مكة، أشارت أم سلمة على النبي ﷺ أن يخرج ويحلق وينحر دون أن يكلم أحدًا.',
    explanation: 'بمجرد ما شاف الصحابة النبي ﷺ بيحلق وينحر، قاموا فورًا وقلّدوه، وده بيبيّن حكمة المرأة المسلمة ومكانتها في استشارات القيادة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D9%85_%D8%B3%D9%84%D9%85%D8%A9',
  ),
  Fact(
    id: 44,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الكعبة المشرفة اتبنت واترُممت عدة مرات مش مرة واحدة',
    body: 'بعد إبراهيم وإسماعيل عليهما السلام، أعادت قريش بناء الكعبة والنبي ﷺ شاب، ثم أعاد بناءها عبد الله بن الزبير ثم الحجاج في عهد عبد الملك بن مروان.',
    explanation: 'قريش لما بنت الكعبة قصّرت النفقة الحلال فتركت جزءًا منها خارج البناء وهو ما يُعرف اليوم بـ «الحِجر» أو حجر إسماعيل، ولذلك الطواف يشمله.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%83%D8%B9%D8%A8%D8%A9',
  ),
  Fact(
    id: 45,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الرحالة ابن بطوطة قطع مسافة تعادل 3 أضعاف مسافة ماركو بولو',
    body: 'سافر الرحالة المغربي ابن بطوطة في القرن الرابع عشر لمدة تقارب 29 عامًا، قاطعًا قرابة 117 ألف كيلومتر عبر إفريقيا وآسيا وأوروبا.',
    explanation: 'اللي ساعده في رحلته إن العالم الإسلامي وقتها كان متصلًا ثقافيًا وقضائيًا؛ اشتغل قاضيًا في دلهي وجزر المالديف ووثق عادات شعوب كتيرة في كتابه «تحفة النظار».',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D8%A8%D9%86_%D8%A8%D8%B7%D9%88%D8%B7%D8%A9',
  ),
  Fact(
    id: 46,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سورة يوسف هي السورة الوحيدة التي سردت قصة نبي كاملة في مكان واحد',
    body: 'تفرّدت سورة يوسف بسرد قصة نبي من بدايتها (رؤياه وهو طفل) حتى نهايتها (لمّ شمل أسرته في مصر) في سورة متصلة واحدة.',
    explanation: 'باقي قصص الأنبياء في القرآن بتتوزع لقطاتها على سور مختلفة حسب سياق كل سورة وهدفها التربوي، بينما سورة يوسف نزلت كاملة لتثبيت قلب النبي ﷺ في عام الحزن.',
    sourceName: 'ويكيبيديا العربية',
