  ),
  Fact(
    id: 47,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'تاج محل ليس مسجدًا بل ضريحًا في مجمع معماري إسلامي مغولي',
    body: 'بنى الإمبراطور المغولي شاه جهان تاج محل في الهند عام 1632م كضريح لزوجته ممتاز محل، ويضم المجمع مسجدًا ودار ضيافة وحدائق متناظرة.',
    explanation: 'استغرق البناء نحو 22 عامًا بمشاركة مهندسين وحرفيين من الهند وفارس وتركيا، ونُقشت على مداخله آيات قرآنية بالخط الثلث تتناسب مع ارتفاع النظر.',
    sourceName: 'ويكيبيديا العربية',
