  ),
  Fact(
    id: 48,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'مريم الإسطرلابية طوّرت أدوات الفلك في القرن العاشر في حلب',
    body: 'عُرفت مريم الإسطرلابية في حلب بصناعة «الإسطرلاب المعقد» في بلاط سيف الدولة الحمداني، وهو جهاز فلكي لحساب مواقع النجوم وأوقات الصلاة.',
    explanation: 'الإسطرلاب كان بمثابة كمبيوتر فلكي محمول للمسلمين؛ يحدد الوقت، والقبلة، والارتفاعات، وخطوط العرض في البحر والصحراء بدقة مبهرة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%B1%D9%8A%D9%85_%D8%A7%D9%84%D8%A5%D8%B3%D8%B7%D8%B1%D9%84%D8%A7%D8%A8%D9%8A%D8%A9',
  ),
  Fact(
    id: 49,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول من جمع سيرة النبي ﷺ ودوّنها بشكل مرتب هو ابن إسحاق',
    body: 'بدأ تدوين السيرة النبوية مبكرًا في عهد التابعين على يد عروة بن الزبير، ثم وضع محمد بن إسحاق كتابه الجامع الذي هذّبه لاحقًا ابن هشام.',
    explanation: 'أشهر كتاب سيرة متداول اليوم هو «سيرة ابن هشام»، وهو في الأصل تهذيب وتنقيح لكتاب ابن إسحاق اللي كتبه في القرن الثاني الهجري.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%B3%D9%8A%D8%B1%D8%A9_%D8%A7%D9%84%D9%86%D8%A8%D9%88%D9%8A%D8%A9_(%D8%A7%D8%A8%D9%86_%D9%87%D8%B4%D8%A7%D9%85)',
  ),
  Fact(
    id: 50,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا استمرت معركة عين جالوت ساعات قصيرة وحسمت مصير العالم؟',
    body: 'في معركة عين جالوت عام 1260م، استخدم المماليك بقيادة قطز وبيبرس تكتيك «الكرّ والفرّ والكمين» لإيقاع جيش المغول الذي لم يُهزم تقريبًا في معركة كبرى قبلها.',
    explanation: 'أهمية المعركة إنها كسرت أسطورة الجيش الذي لا يُقهر، وحمت مصر والمدينة المنورة ومكة وتراث الأمة من التدمير بعد سقوط بغداد.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%B9%D8%B1%D9%83%D8%A9_%D8%B9%D9%8A%D9%86_%D8%AC%D8%A7%D9%84%D9%88%D8%AA',
  ),
  Fact(
    id: 51,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'معجزة الغار لم تكن فقط في الاختباء بل في خطة التموين والاستخبارات',
    body: 'إلى جانب التوكل على الله في غار ثور، خطّط النبي ﷺ لبقائه 3 أيام بتوزيع أدوار دقيقة: أسماء بنت أبي بكر للطعام، وعبد الله للأخبار، وعامر بن فهيرة لمحو الآثار بالغنم.',
    explanation: 'دي قاعدة ذهبية في السيرة: الأخذ بالأسباب والتخطيط بأقصى دقة لا يتعارض أبدًا مع التوكل الكامل على الله.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%87%D8%AC%D8%B1%D8%A9_%D8%A7%D9%84%D9%86%D8%A8%D9%88%D9%8A%D8%A9',
  ),
  Fact(
    id: 52,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سورة الفاتحة فيها 7 آيات لكن لها أكثر من 20 اسمًا عند العلماء',
    body: 'تُسمّى سورة الفاتحة بأسماء متعددة مثل: أم الكتاب، السبع المثاني، الشافية، الوافية، والحمد.',
    explanation: 'كل اسم بيعبر عن جانب من وظيفتها: فهي فاتحة المصحف، وأصل معاني القرآن من التوحيد والعبادة والدعاء، والسبع المثاني لأنها 7 آيات تُقرأ في كل ركعة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D9%81%D8%A7%D8%AA%D8%AD%D8%A9',
  ),
  Fact(
    id: 53,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سُفيان الثوري وعمر بن عبد العزيز وأصل فكرة «تكافل العزّاب»',
    body: 'في عهد الخليفة عمر بن عبد العزيز فاضت خزينة بيت المال بالزكاة لدرجة إن المنادي كان ينادي لتسديد ديون الغارمين وتزويج الشباب غير القادرين.',
    explanation: 'لما العدالة الاقتصادية بتتحقق وتصل الزكاة لمستحقيها بحق، بيتحول المجتمع من مجرد إطعام الجائع لتأهيله وتيسير حياته بالكامل.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B9%D9%85%D8%B1_%D8%A8%D9%86_%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2',
  ),
  Fact(
    id: 54,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الصحابي الذي اهتز لموته عرش الرحمن',
    body: 'ثبت في الصحيحين قول النبي ﷺ عند وفاة الصحابي الجليل سعد بن معاذ: «اهتز عرش الرحمن لموت سعد بن معاذ».',
    explanation: 'سعد أسلم وعمره حوالي 30 سنة ومات وعمره 37 سنة تقريبًا، لكن 7 سنين بس في الإسلام كانت كافية بإخلاصه ونصرته ليكون له المكانة العظيمة دي.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D8%B9%D8%AF_%D8%A8%D9%86_%D9%85%D8%B9%D8%A7%D8%B0',
  ),
  Fact(
    id: 55,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الإسلام لم يعرف طباعة القرآن إلا بعد القرون الأولى لكنه حفظه في الصدور',
    body: 'طُبعت أول نسخة مطبوعة من القرآن في أوروبا في القرن السادس عشر، بينما تأخر انتشار المطابع في العالم الإسلامي للقرن الثامن عشر.',
    explanation: 'رغم كده ظل النص القرآني محفوظًا بنفس الحروف عبر نظام «الإجازة والسند المتصل» والكتابة اليدوية المتقنة على أيدي الخطاطين.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE_%D8%A7%D9%84%D9%82%D8%B1%D8%A2%D9%86',
  ),
  Fact(
    id: 56,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'فكرة الحجر الصحي (Quarantine) طبّقها المسلمون منذ عهد النبي ﷺ',
    body: 'أرشد النبي ﷺ في حديث الطاعون إلى مبدأ العزل الوقائي بقوله: «إذا سمعتم به بأرض فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها فلا تخرجوا فرارًا منه».',
    explanation: 'في القرن الرابع عشر خلال الطاعون الأسود في الأندلس، أكد الطبيب المسلم ابن الخطيب وابن خاتمة وجود «العدوى» بالملاحظة التجريبية وطالبا بعزل المصابين.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D8%A8%D9%86_%D8%A7%D9%84%D8%AE%D8%B7%D9%8A%D8%A8',
  ),
  Fact(
    id: 57,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'غزوة بدر لم تكن مخططة كحرب كبرى بل لاسترداد حق المهاجرين',
    body: 'خرج المسلمون في رمضان عام 2هـ بنحو 313 رجلًا لاعتراض قافلة أبي سفيان التجارية تعويضًا عن أموالهم المصادرة في مكة، فتحول الموقف لمواجهة عسكرية كبرى.',
    explanation: 'لذلك لم يخرج الجميع بسلاح كامل للمعركة، ومع ذلك انتصر المسلمون لصدقهم وتنظيم النبي ﷺ للصفوف واختيار موقع بئر بدر بمشورة الحباب بن المنذر.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%BA%D8%B2%D9%88%D8%A9_%D8%A8%D8%AF%D8%B1',
  ),
  Fact(
    id: 58,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'فدية أسرى بدر كانت تعليم 10 من أبناء المدينة القراءة والكتابة',
    body: 'بعد انتصار بدر، جعل النبي ﷺ فداء الأسير القرشي المتعلم الذي لا يملك مالًا أن يعلّم عشرة من أطفال المسلمين القراءة والكتابة.',
    explanation: 'دي كانت سابقة تربوية رائعة بتحوّل أثر الحرب إلى ثروة تعليمية ترفع نسبة المتعلمين في مجتمع المدينة الناشئ.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%BA%D8%B2%D9%88%D8%A9_%D8%A8%D8%AF%D8%B1',
  ),
  Fact(
    id: 59,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'من الذي أشار على النبي ﷺ بصناعة المنبر ذي الثلاث درجات؟',
    body: 'كان النبي ﷺ يخطب مستندًا إلى جذع نخلة في المسجد النبوي، فلما كثر الناس اقترح صحابي أو امرأة من الأنصار (لها غلام نجار) صنع منبر ليرى الناس وجهه ويسمعوه.',
    explanation: 'استجاب النبي ﷺ لفكرة التطوير العملي دي وصُنع المنبر من خشب الأثل في الغابة بثلاث درجات ليكون التواصل أوضح مع المصلين.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D9%86%D8%A8%D8%B1_%D8%A7%D9%84%D9%86%D8%A8%D9%88%D9%8A',
  ),
  Fact(
    id: 60,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أبو حنيفة النعمان كان تاجر حرير كبيرًا يكتب الفقه في السوق',
    body: 'الإمام أبو حنيفة النعمان، مؤسس أول المذاهب الفقهية الأربعة، لم يكن يعيش من هبات الأمراء، بل كان تاجر خزّ (حرير) معروفًا بأمانته الفائقة في الكوفة.',
    explanation: 'اشتغاله بالتجارة خلّى فقهه واقعيًا جدًا وفاهمًا لحيل السوق والمعاملات، وكان يصرف أرباح تجارته على طلاب العلم أمثال أبي يوسف ومحمد بن الحسن.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%A8%D9%88_%D8%AD%D9%86%D9%8A%D9%81%D8%A9_%D8%A7%D9%84%D9%86%D8%B9%D9%85%D8%A7%D9%86',
  ),
  Fact(
    id: 61,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا كان المسجد النبوي بلا سقف كامل ولا مئذنة في عهد النبي ﷺ؟',
    body: 'بُني المسجد النبوي في البداية بأساس من الحجارة وجدران من اللبن (الطين) وسقف جزئي من جريد النخل، ولم تكن به مآذن.',
    explanation: 'المآذن بدأت تظهر لاحقًا في العهد الأموي لتسهيل سماع الأذان مع اتساع المدن، أما في عهد النبي ﷺ فكان بلال يؤذن من فوق أعلى بيت مجاور للمسجد.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%AC%D8%AF_%D8%A7%D9%84%D9%86%D8%A8%D9%88%D9%8A',
  ),
  Fact(
    id: 62,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الصحابي الملقب بـ «حِبر الأمة» وترجمان القرآن',
    body: 'عبد الله بن عباس، ابن عم النبي ﷺ، كان طفلًا عند وفاة الرسول، ومع ذلك صار من أعلم الصحابة بتفسير القرآن بفضل دعاء النبي ﷺ له: «اللهم فقهه في الدين وعلمه التأويل».',
    explanation: 'كان ابن عباس يسأل كبار الصحابة ويعقل المعاني ويدوّنها حتى صار مرجعًا للخلفاء والعلماء رغم صغر سنه.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D9%84%D9%87_%D8%A8%D9%86_%D8%B9%D8%A8%D8%A7%D8%B3',
  ),
  Fact(
    id: 63,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'جزيرة صقلية كانت إمارة إسلامية مزدهرة لأكثر من قرنين',
    body: 'حكم المسلمون جزيرة صقلية الإيطالية من القرن التاسع إلى القرن الحادي عشر، وأدخلوا إليها زراعة الليمون والبرتقال والفستق ونظم الري المتطورة.',
    explanation: 'حتى بعد سقوط الحكم الإسلامي، استعان الملوك النورمان بالعلماء المسلمين مثل الإدريسي الذي رسم أدق خريطة للعالم وقتها في كتابه «نزهة المشتاق».',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A5%D9%85%D8%A7%D8%B1%D8%A9_%D8%B5%D9%82%D9%84%D9%8A%D8%A9',
  ),
  Fact(
    id: 64,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أقدم مصحف مخطوط كامل تقريبًا محفوظ في طشقند وإسطنبول وبرمنغهام',
    body: 'تحتفظ جامعة برمنغهام البريطانية برقوق قرآنية يعود تاريخ الكربون المشع لها إلى الفترة بين 568م و645م، أي في زمن قريب جدًا من زمن النبي ﷺ وصحابته.',
    explanation: 'الدراسات الحديثة على المخطوطات القرآنية القديمة بتؤكد تطابق النص القرآني عبر القرون دون تحريف.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%AE%D8%B7%D9%88%D8%B7%D8%A9_%D8%A7%D9%84%D9%82%D8%B1%D8%A2%D9%86_%D8%A8%D8%AC%D8%A7%D9%85%D8%B9%D8%A9_%D8%A8%D8%B1%D9%85%D9%86%D8%BA%D9%87%D8%A7%D9%85',
  ),
  Fact(
    id: 65,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا استمرت الدعوة السرية في مكة 3 سنوات بالضبط؟',
    body: 'بدأت الدعوة في مكة سرية لمدة 3 سنوات في دار الأرقم بن أبي الأرقم قبل أن ينزل الأمر: «فَاصْدَعْ بِمَا تُؤْمَرُ».',
    explanation: 'الفترة السرية دي كانت لبناء نواة صلبة من المؤمنين القادرين على تحمّل الأذى، عشان لما تبدأ الدعوة الجهرية يكون في صف متماسك يحميها.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AF%D8%A7%D8%B1_%D8%A7%D9%84%D8%A3%D8%B1%D9%82%D9%85',
  ),
  Fact(
    id: 66,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'القائد الذي لم يُهزم في أي معركة خاضها لا في الجاهلية ولا في الإسلام',
    body: 'خاض خالد بن الوليد رضي الله عنه عشرات المعارك ضد الفرس والروم والمرتدين ولم يُهزم في معركة واحدة، ولقّبه النبي ﷺ بـ «سيف الله المسلول».',
    explanation: 'اللافت إن خالد مات على فراشه وهو حزين إنه لم ينل الشهادة، وقال كلمته الشهيرة: «ما في جسدي موضع شبر إلا وفيه ضربة بسيف أو رمية بسهم، وها أنا أموت على فراشي».',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AE%D8%A7%D9%84%D8%AF_%D8%A8%D9%86_%D8%A7%D9%84%D9%88%D9%84%D9%8A%D8%AF',
  ),
  Fact(
    id: 67,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'مسجد قرطبة تحوّل لكاتدرائية لكنه احتفظ بأقواسه الأندلسية الشهيرة',
    body: 'بُني جامع قرطبة الكبير عام 784م على يد عبد الرحمن الداخل، واشتهر بأقواسه المزدوجة المخططة بالأحمر والأبيض التي صُممت لرفع السقف وزيادة الإضاءة.',
    explanation: 'الهندسة المعمارية للجامع استخدمت أعمدة مزدوجة لتوزيع الوزن وتخفيف الضغط، وهي عبقرية هندسية ما زالت تدهش المعماريين.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%B3%D8%AC%D8%AF_%D9%82%D8%B1%D8%B7%D8%A8%D8%A9',
  ),
  Fact(
    id: 68,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول امرأة دخلت الإسلام ليست خديجة فقط في بيتها بل أسلمت معها بناتها',
    body: 'آمنت السيدة خديجة بنت خويلد بالنبي ﷺ في اللحظة الأولى بعد نزول الوحي، وساندته بمالها ونفسها وقالت له: «كلا والله لا يخزيك الله أبدًا».',
    explanation: 'استحقاق خديجة لسلام خاص من الله عز وجل عبر جبريل عليه السلام وبشرى ببيت في الجنة من قصب لا صخب فيه ولا نصب كان مكافأة لوقوفها البطولي في أصعب سنوات الدعوة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AE%D8%AF%D9%8A%D8%AC%D8%A9_%D8%A8%D9%86%D8%AA_%D8%AE%D9%88%D9%8A%D9%84%D8%AF',
  ),
  Fact(
    id: 69,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا يوجد «صلاة الكسوف» بركوعين في كل ركعة؟',
    body: 'يوم وفاة إبراهيم ابن النبي ﷺ، انكسفت الشمس، فظن بعض الناس إنها انكسفت حزنًا على موته، فصحح النبي ﷺ الفكرة فورًا.',
    explanation: 'قال ﷺ: «إن الشمس والقمر آيتان من آيات الله لا ينكسفان لموت أحد ولا لحياته»، وصلّى بالناس صلاة الكسوف التي تختلف عن باقي الصلوات بوجود ركوعين في كل ركعة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B5%D9%84%D8%A7%D8%A9_%D8%A7%D9%84%D9%83%D8%B3%D9%88%D9%81',
  ),
  Fact(
    id: 70,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'طريق الحرير البحري نشر الإسلام في الهند وسريلانكا قبل الجيوش',
    body: 'أسس التجار العرب والمسلمون جاليات تجارية مزدهرة على سواحل كيرالا الهندية وسريلانكا في القرن السابع الميلادي، وبنوا هناك من أقدم المساجد في آسيا.',
    explanation: 'مسجد «تشيرامان جمعة» في كيرالا الهندية يرجع تاريخ تأسيسه التقليدي لمنتصف القرن السابع، وده بيعكس دور الأمانة التجارية في انتشار الإسلام.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%B3%D8%AC%D8%AF_%D8%AA%D8%B4%D9%8A%D8%B1%D8%A7%D9%85%D8%A7%D9%86_%D8%AC%D9%85%D8%B9%D8%A9',
  ),
  Fact(
    id: 71,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سُبُل الأندلس في الموسيقى وتأثير زرياب على الموضة والذوق العام',
    body: 'في القرن التاسع في قرطبة، أسس العالم والموسيقي زرياب أول معهد موسيقي، وأضاف الوتر الخامس للعود، وغيّر عادات الأكل والموضة الموسمية.',
    explanation: 'زرياب هو اللي عوّد الناس على تقديم الطعام في أطباق متتابعة (مقبلات ثم طبق رئيسي ثم حلوى) وتغيير لون الملابس بين الصيف والشتاء.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B2%D8%B1%D9%8A%D8%A7%D8%A8',
  ),
  Fact(
    id: 72,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'سورة العلق هي أول ما نزل، لكن سورة النصر آخر سورة كاملة نزولًا',
    body: 'ترتيب السور في المصحف لا يتبع ترتيب نزولها الزمني؛ فأول ما نزل آيات سورة العلق، بينما سورة النصر كانت آخر سورة نزلت كاملةً.',
    explanation: 'أدرك كبار الصحابة مثل ابن عباس وعمر بن الخطاب إن سورة النصر نعيٌ لقرب رحيل النبي ﷺ بعد تمام الرسالة ودخول الناس في دين الله أفواجًا.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D9%86%D8%B5%D8%B1',
  ),
  Fact(
    id: 73,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'مكتبة شنقيط في موريتانيا تحفظ آلاف المخطوطات في بيوت عائلات في الصحراء',
    body: 'مدينة شنقيط في موريتانيا تُعد واحدة من أعرق مدن العلم الإسلامية، حيث تحتفظ عائلاتها بمكتبات خاصة تضم آلاف المخطوطات النادرة وسط الصحراء.',
    explanation: 'اشتهر الشناقطة بقوة الحفظ وإتقان العلوم اللغوية والفقهية رغم شظف العيش في الصحراء، وصاروا يُعرفون في المشرق بـ «علماء المحاظر».',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B4%D9%86%D9%82%D9%8A%D8%B7',
  ),
  Fact(
    id: 74,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'ما معنى «إيلاف قريش» الذي ذكره القرآن الكريم؟',
    body: 'الإيلاف في سورة قريش يشير إلى المعاهدات التجارية الآمنة التي عقدها هاشم بن عبد مناف مع ملوك الشام واليمن والحبشة وفارس لحماية قوافل قريش.',
    explanation: 'قريش كانت بتطلع رحلتين في السنة: لليمن في الشتاء وللشام في الصيف، وربنا ذكّرهم بالنعمة دي عشان يشكروا رب هذا البيت اللي أمّنهم من الخوف والجوع.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D9%82%D8%B1%D9%8A%D8%B4',
  ),
  Fact(
    id: 75,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الإمام الشافعي أتقن الفقه في مكة والمدينة والعراق ومصر',
    body: 'يتميز مذهب الإمام الشافعي بأنه جمع بين «مدرسة الحديث» في المدينة عند مالك، و«مدرسة الرأي» في العراق عند تلاميذ أبي حنيفة، ثم طوّر مذهبه الجديد في مصر.',
    explanation: 'تنقله بين أربع مدارس وبيئات ثقافية مختلفة خلاه يضع قواعد علم «أصول الفقه» في كتابه «الرسالة» كأول منهج مكتوب لفهم الأحكام.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%B4%D8%A7%D9%81%D8%B9%D9%8A',
  ),
  Fact(
    id: 76,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'معركة اليرموك شهدت مشاركة نساء مسلمات في الصفوف لرد المنسحبين',
    body: 'في معركة اليرموك الفاصلة عام 15هـ، لعبت الصحابيات مثل خولة بنت الأزور وأسماء بنت أبي بكر وهند بنت عتبة دورًا في تشجيع المقاتلين ومداواة الجرحى.',
    explanation: 'لما ضغط الروم على جناح من الجيش الإسلامي، وقفت النساء بأعمدة الخيام ينادين في الرجال للثبات وعدم التراجع حتى تحقق النصر.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D9%85%D8%B9%D8%B1%D9%83%D8%A9_%D8%A7%D9%84%D9%8A%D8%B1%D9%85%D9%88%D9%83',
  ),
  Fact(
    id: 77,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'قصة الصحابي الذي أسره الروم وعُرض عليه الملك مقابل التنصر فرفض',
    body: 'أُسر عبد الله بن حذافة السهمي مع مسلمين آخرين في عهد عمر بن الخطاب، وعرض عليه هرقل نصف ملكه ليرتد فرفض، فهدده بالقتل فابتسم.',
    explanation: 'لما سأله الإمبراطور لماذا تبكي عند وضع القدر المغلي، قال أبكي لأن لي نفسًا واحدة ووددت لو لي بعدد شعر رأسي أنفس تُلقى في سبيل الله؛ فأُعجب هرقل وأطلق سراحه مع الأسرى مقابل أن يقبل رأسه.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D9%84%D9%87_%D8%A8%D9%86_%D8%AD%D8%B0%D8%A7%D9%81%D8%A9_%D8%A7%D9%84%D8%B3%D9%87%D9%85%D9%8A',
  ),
  Fact(
    id: 78,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'لماذا استمرت خلافة أبي بكر الصديق سنتين فقط لكنها حمت بقاء الدولة؟',
    body: 'تولّى أبو بكر الخلافة عامين و3 أشهر فقط، واجه خلالها حروب الردة وادعاء النبوة ثم أطلق فتوحات العراق والشام وجمع القرآن.',
    explanation: 'الحزم السريع في مواجهة الردة مع إنفاذ جيش أسامة بن زيد استرد هيبة الدولة الإسلامية في لحظة حرجة جدًا بعد وفاة النبي ﷺ.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%A8%D9%88_%D8%A8%D9%83%D8%B1_%D8%A7%D9%84%D8%B5%D8%AF%D9%8A%D9%82',
  ),
  Fact(
    id: 79,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أبو بكر الرازي ميز لأول مرة بين الجدري والحصبة في كتاب طبي دقيق',
    body: 'قبل الطب الحديث بمئات السنين، كتب الطبيب المسلم أبو بكر الرازي في القرن العاشر رسالة علمية متخصصة فرّق فيها سريريًا بين الجدري والحصبة.',
    explanation: 'الرازي كمان لما طلبوا منه اختيار موقع لبناء مستشفى في بغداد، علّق قطع لحم في مناطق مختلفة من المدينة واختار المكان اللي اللحم اتأخر فيه عن التعفن لأن هواه أنقى.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%A8%D9%88_%D8%A8%D9%83%D8%B1_%D8%A7%D9%84%D8%B1%D8%A7%D8%B2%D9%8A',
  ),
  Fact(
    id: 80,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الزهراوي اخترع أكثر من 200 أداة جراحية ما زال بعضها مستعملًا للآن',
    body: 'وضع الجراح الأندلسي أبو القاسم الزهراوي في القرن العاشر موسوعة «التصريف لمن عجز عن التأليف» وصمّم فيها المقص الجراحي والمشرط والخيوط القابلة للذوبان.',
    explanation: 'الزهراوي اكتشف إن خيوط أمعاء الحيوانات (Catgut) بتدوب جوه الجسم من غير ما تسبب التهاب أو تحتاج فك غرز تاني.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%A8%D9%88_%D8%A7%D9%84%D9%82%D8%A7%D8%B3%D9%85_%D8%A7%D9%84%D8%B2%D9%87%D8%B1%D8%A7%D9%88%D9%8A',
  ),
  Fact(
    id: 81,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'كم استمر بناء مسجد قبة الصخرة وما علاقته بالمسجد الأقصى؟',
    body: 'بنى الخليفة عبد الملك بن مروان مسجد قبة الصخرة في القدس عام 691م، وهو جزء من الحرم القدسي الشريف وليس كل المسجد الأقصى.',
    explanation: 'المسجد الأقصى اسم يطلق على كامل المساحة المسوّرة في القدس (حوالي 144 دونمًا)، وتضم الجامع القبلي وقبة الصخرة والمصلى المرواني والساحات.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%85%D8%B3%D8%AC%D8%AF_%D8%A7%D9%84%D8%A3%D9%82%D8%B5%D9%89',
  ),
  Fact(
    id: 82,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'نظام الحسبة كان يشمل مراقبة نظافة الخبز وساعات عمل البغال',
    body: 'لم يقتصر «المحتسب» في المدن الإسلامية على الغش التجاري، بل كان يراقب تغطية اللحوم في الأسواق، ونظافة الأفران، وعدم تحميل الدواب فوق طاقتها.',
    explanation: 'كُتب الحسبة القديمة بتكشف وعيًا مدنيًا متقدمًا بحقوق المستهلك والصحة العامة والرفق بالحيوان.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AD%D8%B3%D8%A8%D8%A9',
  ),
  Fact(
    id: 83,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'العز بن عبد السلام باع الأمراء المماليك في مزاد قبل تحريرهم',
    body: 'رفض العالم الملقب بسلطان العلماء «العز بن عبد السلام» تولي الأمراء المماليك قيادة الدولة ما داموا في حكم الرق لبيت المال، فأصر على بيعهم أولًا ثم تحريرهم.',
    explanation: 'القصة بتورينا قوة القضاء المستقل ومكانة العلماء في محاسبة الحكام وتطبيق القانون على الكبار قبل الصغار.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%B9%D8%B2_%D8%A8%D9%86_%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  ),
  Fact(
    id: 84,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الساعة الفيل التي صنعها الجزري في القرن الثاني عشر',
    body: 'صمّم المهندس المسلم بديع الزمان الجزري «ساعة الفيل» الميكانيكية المائية، وهي ساعة معقدة كانت تعلن مرور كل نصف ساعة بأصوات وحركات ميكانيكية دقيقة.',
    explanation: 'الجزري وثّق تصميماتها الهندسية في كتاب «الجامع بين العلم والعمل النافع في صناعة الحيل»، ومنها تروس وأذرع تحويل الحركة الدائرية لحركة خطية.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%8A%D8%B9_%D8%A7%D9%84%D8%B2%D9%85%D8%A7%D9%86_%D8%A7%D9%84%D8%AC%D8%B2%D8%B1%D9%8A',
  ),
  Fact(
    id: 85,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'صلاح الدين الأيوبي أرسل طبيبه الخاص لعلاج خصمه ريتشارد قلب الأسد',
    body: 'أثناء الحروب الصليبية، عندما أصيب الملك الإنجليزي ريتشارد قلب الأسد بالحمى، أرسل له صلاح الدين الأيوبي فواكه طازجة وثلجًا وطبيبًا للمساعدة في علاجه.',
    explanation: 'الفروسية والأخلاق الإسلامية في الحرب خلت حتى أعداء صلاح الدين في أوروبا يكتبون عنه بإجلال واحترام كبيرين.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B5%D9%84%D8%A7%D8%AD_%D8%A7%D9%84%D8%AF%D9%8A%D9%86_%D8%A7%D9%84%D8%A3%D9%8A%D9%88%D8%A8%D9%8A',
  ),
  Fact(
    id: 86,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الإمام البصري الحسن البصري كان يردّ على السائل بتعليم السلوك لا الكلام فقط',
    body: 'طلب بعض المماليك من الحسن البصري أن يخطب في فضيلة عتق العبيد، فلم يتكلم في جمعة واحدة حتى اشترى مملوكًا وأعتقه أولًا ثم خطب في الناس.',
    explanation: 'القدوة العملية عند علماء السلف كانت بتسبق الموعظة بالكلام؛ لذلك كان لكلامهم أثر عظيم في نفوس الناس.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D8%AD%D8%B3%D9%86_%D8%A7%D9%84%D8%A8%D8%B5%D8%B1%D9%8A',
  ),
  Fact(
    id: 87,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الإمام أحمد بن حنبل حفظ مليون حديث على سبيل الاستيعاب والتدقيق',
    body: 'امتلك الإمام أحمد بن حنبل ذاكرة حديثية استثنائية، وجمع في كتابه «المسند» قرابة 27 ألف حديث مع المكرر بعد انتقائها من مئات الآلاف من الروايات.',
    explanation: 'الشيء المدهش إنه لم يقبل المال في محنته ولا بعد خروجه منها، وعاش زاهدًا متواضعًا حتى صار رمزًا للثبات العلمي والأخلاقي.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%A8%D9%86_%D8%AD%D9%86%D8%A8%D9%84',
  ),
  Fact(
    id: 88,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'مؤتمر السقيفة أسّس لمفهوم الشورى في انتقال السلطة لأول مرة',
    body: 'بعد وفاة النبي ﷺ مباشرة اجتمع الأنصار والمهاجرون في سقيفة بني ساعدة لحسم مسألة القيادة وتجنب فراغ السلطة، وانتهى النقاش بمبايعة أبي بكر الصديق.',
    explanation: 'رغم حدة النقاش في البداية، تغلب منطق الحوار والاتفاق على مصلحة الأمة العليا وتجنب الانقسام.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%82%D9%8A%D9%81%D8%A9_%D8%A8%D9%86%D9%8A_%D8%B3%D8%A7%D8%B9%D8%AF%D8%A9',
  ),
  Fact(
    id: 89,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'الصحابي الذي غسّلته الملائكة يوم أحد',
    body: 'حنظلة بن أبي عامر استشهد في غزوة أحد بعد ما خرج من بيته فور سماعه نداء القتال قبل أن يغتسل من ليلة زفافه، فأخبر النبي ﷺ إنه رأى الملائكة تغسله.',
    explanation: 'سُمي بعدها بـ «غسيل الملائكة»، والموقف بيعكس سرعة استجابة الصحابة للواجب وتقديم نداء الدين على متع الدنيا.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AD%D9%86%D8%B8%D9%84%D8%A9_%D8%A8%D9%86_%D8%A3%D8%A8%D9%8A_%D8%B9%D8%A7%D9%85%D8%B1',
  ),
  Fact(
    id: 90,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أمر النبي ﷺ بكتابة المعاهدات ونقش خاتم رسمي خاص بالدولة',
    body: 'لما أراد النبي ﷺ إرسال رسائل للملوك والأمراء مثل هرقل وكسرى، قيل له إن الملوك لا يقرؤون كتابًا غير مختوم، فاتخذ خاتمًا من فضة نقشه «محمد رسول الله».',
    explanation: 'النبي ﷺ ما رفضش الأعراف الدبلوماسية الدولية بل تفاعل معها بحكمة وبساطة عشان يوصل رسالته بأفضل صورة رسمية.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AE%D8%A7%D8%AA%D9%85_%D8%A7%D9%84%D9%86%D8%A8%D9%8A_%D9%85%D8%AD%D9%85%D8%AF',
  ),
  Fact(
    id: 91,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'بريد الحمام الزاجل كان خدمة رسمية سريعة في مصر والشام المملوكية',
    body: 'أسس السلطان نور الدين زنكي ثم الظاهر بيبرس شبكة «أبراج الحمام الزاجل» التي كانت تنقل الرسائل بين القاهرة ودمشق خلال ساعات قليلة.',
    explanation: 'كان لكل طائر بطاقة تعريف ومكان تسجيل في الدواوين، وده وفّر نظام اتصالات أسرع من الخيل بعشرات المرات وقت الحروب.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%AD%D9%85%D8%A7%D9%85_%D8%B2%D8%A7%D8%AC%D9%84',
  ),
  Fact(
    id: 92,
    category: 'دين وسيرة وتاريخ إسلامي',
    title: 'أول ما يقرأه المسلم في سورة البقرة يبدأ بوصف الكتاب ثم تقسيم الناس 3 أصناف',
    body: 'تبدأ سورة البقرة بأول خمس آيات عن المتقين، ثم آيتين عن الكافرين، ثم 13 آية كاملة عن المنافقين.',
    explanation: 'تخصيص 13 آية للمنافقين مقابل آيتين بس للكافر الصريح يوضح قد إيه خطر الخداع الداخلي والازدواجية أصعب وأكثر تعقيدًا من العداوة الواضحة.',
    sourceName: 'ويكيبيديا العربية',
    url: 'https://ar.wikipedia.org/wiki/%D8%B3%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D8%A8%D9%82%D8%B1%D8%A9',
  ),
  Fact(
    id: 93,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'ليه الحاجة الناقصة بتفضل في دماغك أكتر من اللي خلصتها؟',
    body: 'يميل العقل البشري لتذكر المهام غير المكتملة أو المقطوعة أكثر بكثير من المهام التي أتمها، وتُعرف الظاهرة بـ «تأثير زيجارنيك».',
    explanation: 'لو بدأت شغل وسبته في النص هتلاقيه بيلح عليك طول اليوم. الحل العملي: اكتب خطوتك الجاية في ورقة قبل ما تقوم، عشان مخك يطمن إن الملف محفوظ فيرتاح.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Zeigarnik_effect',
  ),
  Fact(
    id: 94,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الناس مش مركزة معاك ولا مع غلطتك زي ما أنت متخيل',
    body: 'نبالغ عادةً في تقدير مدى ملاحظة الآخرين لأخطائنا أو مظهرنا، ويُسمى ذلك «تأثير الأضواء» (Spotlight Effect).',
    explanation: 'في تجربة شهيرة بجامعة كورنيل، طلبوا من طلاب يلبسوا تيشرت محرج وتوقعوا إن نص القاعة هتلاحظه، لكن الحقيقة إن أقل من 25% انتبهوا. كل واحد مشغول بمسرحه الخاص.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Spotlight_effect',
  ),
  Fact(
    id: 95,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'ليه السعادة بالمشتريات الجديدة بتطير بسرعة؟',
    body: 'يتأقلم الإنسان سريعًا مع التحسن المادي أو الترقية ويعود لمستوى سعادته الاعتيادي خلال أشهر، وهو ما يُسمى «التكيّف المُتعي» (Hedonic Adaptation).',
    explanation: 'عشان كده الموبايل أو العربية الجديدة بيفرحوك شوية وبعدين يبقوا عاديين، بينما التجارب والعلاقات والامتنان بتدوم سعادتهم أطول لأنها بتتجدد ومش بتتحول لديكور ثابت.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Hedonic_treadmill',
  ),
  Fact(
    id: 96,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'اطلب خدمة صغيرة من حد تكسب محبته أكتر',
    body: 'يميل الشخص لأن يحب من أسدى له معروفًا أكثر مما يحب من قدّم له معروفًا، وهي مفارقة تُسمى «تأثير بنجامين فرانكلين».',
    explanation: 'السبب إن العقل بيكره التناقض المعرفي؛ لما تساعد حد، مخك بيقول لنفسه «أنا أكيد بحب الشخص ده عشان كده ساعدته»، فطلب خدمة بسيطة ومناسبة ممكن يقرّب المسافات.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Ben_Franklin_effect',
  ),
  Fact(
    id: 97,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'عقلك يقدر يدير حوالي 150 علاقة اجتماعية مستقرة بس',
    body: 'اقترح عالم الأنثروبولوجيا روبن دانبار أن الحد الإدراكي لحجم الدوائر الاجتماعية المستقرة للإنسان يدور حول 150 شخصًا تقريبًا.',
    explanation: 'السوشيال ميديا بتخليك تتابع آلاف، لكن طاقتك النفسية الفعلية للثقة والاهتمام محدودة؛ فاستثمر وقتك في الـ 5 المقربين والـ 15 دايرة الدعم الحقيقية.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Dunbar%27s_number',
  ),
  Fact(
    id: 98,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير دانينغ-كروغر: كل ما تقل الخبرة تزيد الثقة الزائدة أحيانًا',
    body: 'أظهرت أبحاث دانينغ وكروغر أن المبتدئين في مجال ما يميلون لتقدير مهاراتهم بأعلى من الواقع، بينما يشكك الخبراء أحيانًا في قدراتهم.',
    explanation: 'الخبير عارف حجم اللي لسه ما يعرفوش، أما المبتدئ فمش شايف تعقيدات المجال. التواضع المعرفي والفضول هما مفتاح تعدّي «قمة الجهل» للوصول للإتقان.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Dunning%E2%80%93Kruger_effect',
  ),
  Fact(
    id: 99,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'متلازمة المحتال بتصيب أنجح الناس مش الفاشلين',
    body: 'يعيش كثير من الناجحين شعورًا خفيًا بأنهم «محتالون» وأن نجاحهم مجرد حظ رغم الأدلة الواضحة على كفاءتهم، وتُعرف بـ «ظاهرة المحتال».',
    explanation: 'إحساسك إنك لسه محتاج تتعلم طبيعي جدًا ومش دليل نقص؛ فرّق بين مشاعرك وبين سجل إنجازاتك الحقيقي على الورق.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Impostor_syndrome',
  ),
  Fact(
    id: 100,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'قاعدة الدقيقتين لتكوين أي عادة جديدة من غير مقاومة',
    body: 'عند بدء عادة جديدة، ينصح خبراء السلوك بتقليصها لنسخة تستغرق دقيقتين فقط بدل البدء بهدف ضخم، لتقليل احتكاك البدء.',
    explanation: 'بدل «هقرأ ساعة كل يوم» ابدأ بـ «هقرأ صفحة واحدة». عقلك مش هيحس بتهديد أو كسل، ولما تبدأ الدقيقتين غالبًا هتكمل لوحدك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Habit',
  ),
  Fact(
    id: 101,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'لماذا نحكم على غيرنا بطباعهم وعلى أنفسنا بالظروف؟',
    body: 'نفسّر أخطاء الآخرين غالبًا بأنها عيب في شخصيتهم، بينما نبرر أخطاءنا بضغط الظروف، وهو تحيز يُسمى «خطأ الإسناد الأساسي».',
    explanation: 'لو حد اتأخر بنقول «شخص مستهتر»، ولو إحنا اتأخرنا بنقول «المواصلات زحمة». الوعي بالتحيز ده بيخليك أكثر عدلًا ورحمة في علاقاتك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Fundamental_attribution_error',
  ),
  Fact(
    id: 102,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مفارقة الاختيار: لما الاختيارات بتزيد سعادتنا بالقرار بتقل',
    body: 'أثبت عالم النفس باري شوارتز أن كثرة البدائل المتاحة لا تزيد الرضا دائمًا، بل قد تسبب شلل القرار والندم بعد الاختيار.',
    explanation: 'في تجربة شهيرة للمربى في السوبرماركت، الناس اشترت أكتر بـ 10 مرات لما اتعرض لها 6 أنواع مقارنةً بـ 24 نوع! البساطة بتحمي طاقة قراراتك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/The_Paradox_of_Choice',
  ),
  Fact(
    id: 103,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'ألم الخسارة يوجع ضعف فرحة المكسب المساوي له',
    body: 'في علم النفس السلوكي ونظرية الاحتمال، يشعر الإنسان بألم خسارة 100 جنيه بما يعادل تقريبًا ضعف سعادته بربح 100 جنيه.',
    explanation: 'الظاهرة دي اسمها «النفور من الخسارة» (Loss Aversion)، وهي السبب إننا بنخاف نغيّر شغل ممل أو نسيب علاقة مؤذية رغم إن المكسب في التغيير أكبر.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Loss_aversion',
  ),
  Fact(
    id: 104,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'التفكير في الغلطة في سطر مكتوب بيقلل القلق أسرع من التفكير في الرأس',
    body: 'الكتابة التعبيرية وتسمية المشاعر (Affect Labeling) تقلل نشاط اللوزة الدماغية المسؤولة عن الخوف والانفعال بنسبة ملحوظة.',
    explanation: 'مجرد ما تقول أو تكتب: «أنا حاسس بتوتر وخوف من الرفض دلوقتي»، عقلك بينقل الشعور من مركز الذعر إلى قشرة الدماغ التحليلية فتهدأ.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Affect_labeling',
  ),
  Fact(
    id: 105,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'أثر «إيكيا»: بنحب الحاجة اللي تعبنا في تركيبها حتى لو معووجة',
    body: 'يعطي الناس قيمة أعلى للأشياء التي ساهموا في بنائها أو تجميعها بأيديهم مقارنةً بالأشياء الجاهزة، ويُسمى «تأثير إيكيا».',
    explanation: 'نفس المبدأ في العلاقات والشغل؛ لما تدي شريكك أو فريقك مساحة يشارك في بناء الفكرة مش مجرد تنفيذها، هيدافع عنها ويحبها أكتر.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/IKEA_effect',
  ),
  Fact(
    id: 106,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير التعرّض المتكرر: الألفة تصنع القبول قبل الإقناع',
    body: 'كلما تكرر تعرضنا لشيء أو شخص أو فكرة في سياق محايد أو إيجابي، زاد ميلنا لحبه وتقبله، وهو «تأثير التعرّض المجرد».',
    explanation: 'التواجد الهادئ والمستمر بلطف في حياة الناس أو أمام مهارة بتتعلمها بيكسر الغربة تلقائيًا من غير مجهود ضخم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Mere-exposure_effect',
  ),
  Fact(
    id: 107,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'العمل يمتد ليملأ كل الوقت المتاح له (قانون باركنسون)',
    body: 'صاغ المؤرخ سيريل باركنسون قانونًا شهيرًا يقول إن المهمة تتمدد لتستغرق كل الوقت المتاح لإنجازها.',
    explanation: 'لو عندك تقرير ومديله أسبوع هيخلص في أسبوع، ولو ضغطت نفسك بساعتين ممكن تخلص 80% منه بتركيز أعلى. تحديد موعد تسليم ضيق وواقعي بيحارب التسويف.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Parkinson%27s_law',
  ),
  Fact(
    id: 108,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مبدأ باريتو 80/20: 20% من أفعالك بتجيب 80% من نتايجك',
    body: 'لاحظ الاقتصادي فيلفريدو باريتو إن نحو 80% من النتائج تأتي من 20% فقط من الأسباب أو الجهود المركزة.',
    explanation: 'بدل ما تغرق في 20 مهمة تافهة عشان تحس بالإنجاز، اسأل نفسك كل صباح: إيه المهمتين اللي لو خلصتهم النهارده يومي هيبقى ناجح؟',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Pareto_principle',
  ),
  Fact(
    id: 109,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مغالطة التكلفة الغارقة بتخلينا نكمل في طريق غلط لمجرد إننا دفعنا فيه وقت',
    body: 'يستمر البشر أحيانًا في مشاريع أو علاقات خاسرة فقط لأنهم استثمروا فيها وقتًا أو مالًا سابقًا، وهو ما يُسمى «مغالطة التكلفة الغارقة».',
    explanation: 'الوقت اللي فات راح خلاص؛ القرار الصح يتبني على «هل لو بدأت النهارده من الصفر هدخل الطريق ده؟» لو الإجابة لأ، فالانسحاب ربح مش خسارة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Sunk_cost',
  ),
  Fact(
    id: 110,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الحديث عن أهدافك قبل تنفيذها قد يقلل حماسك لتحقيقها',
    body: 'أشارت أبحاث عالم النفس بيتر غولفيتزر إلى أن إعلان الأهداف والحصول على إطراء الناس مبكرًا يمنح المخ «مكافأة بديلة» توهمه بالإنجاز.',
    explanation: 'عشان كده «استعينوا على قضاء حوائجكم بالكتمان» لها سند نفسي قوي؛ احتفظ بخطتك لنفسك أو لشريك محاسبة حقيقي وخلي النتيجة هي اللي تتكلم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Implementation_intention',
  ),
  Fact(
    id: 111,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «بيجماليون»: توقعاتك في الآخرين قد تخلق واقعهم فعلًا',
    body: 'أثبتت تجارب روزنتال أن ارتفاع توقعات المعلم أو المدير تجاه شخص ما يؤدي فعليًا إلى تحسن أداء ذلك الشخص.',
    explanation: 'لما تعامل ابنك أو زميلك على إنه ذكي وقادر، نبرتك وصبرك ودعمك بيتغيروا لاشعوريًا فبتطلّع منه أحسن نسخة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Pygmalion_effect',
  ),
  Fact(
    id: 112,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'حالة «التدفق» (Flow): قمة السعادة والإنتاجية في التحدي المتوازن',
    body: 'وصف عالم النفس ميهالي تشيكسنتميهالي حالة «التدفق» بأنها الانغماس الكامل في نشاط صعب بما يكفي ليتحدّاك، لكنه ليس مستحيلًا ليصيبك بالقلق.',
    explanation: 'لو المهمة أسهل من مهارتك بتحس بالملل، ولو أصعب بكتير بتتوتر. السحر بيحصل لما تزود التحدي 5–10% فوق مستواك الحالي.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Flow_(psychology)',
  ),
  Fact(
    id: 113,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'التسويف ليس مشكلة تنظيم وقت بل مشكلة تنظيم مشاعر',
    body: 'تؤكد الأبحاث النفسية الحديثة أن التسويف سببه الأساسي الهروب من مشاعر مزعجة مرتبطة بالمهمة مثل الخوف من الفشل أو الملل أو التشتت، لا الكسل.',
    explanation: 'لما تلاقي نفسك بتأجل مهمة، اسأل نفسك: «أنا خايف من إيه في المهمة دي؟» غالبًا بمجرد تقسيمها لأول خطوة صغيرة غير مخيفة، العقدة بتتفك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Procrastination',
  ),
  Fact(
    id: 114,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'قاعدة الـ 5/1 في العلاقات المستقرة (أبحاث جون غوتمان)',
    body: 'توصّل الباحث جون غوتمان بعد دراسة آلاف الأزواج إلى أن العلاقات المستقرة تحتوي على ما لا يقل عن 5 تفاعلات إيجابية مقابل كل تفاعل سلبي واحد وقت الخلاف.',
    explanation: 'المجاملات الصادقة، والضحك المشترك، والاهتمام بالتفاصيل الصغيرة في الأيام العادية هي الرصيد اللي بيشيل العلاقة وقت الخناقات.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/John_Gottman',
  ),
  Fact(
    id: 115,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'أربع علامات قاتلة للزواج والعلاقات سمّاها غوتمان «الفرسان الأربعة»',
    body: 'حدّد غوتمان أربعة أنماط تواصل تتنبأ بانهيار العلاقات بدقة عالية: النقد الحاد للذات، الاحتقار، الدفاعية، والانسحاب الصامت (Stonewalling).',
    explanation: 'أخطرها على الإطلاق هو «الاحتقار» (السخرية أو التقليل من شأن الطرف التاني)، وعلاجه هو بناء ثقافة التقدير والاحترام والتعبير عن الحاجة بدل الهجوم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/John_Gottman',
  ),
  Fact(
    id: 116,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'التحول من المهام بين التطبيقات بيضيع لحد 23 دقيقة تركيز',
    body: 'تشير أبحاث غلوريا مارك في جامعة كاليفورنيا إلى أن العودة إلى التركيز العميق بعد مقاطعة بسيطة أو إشعار هاتف قد تستغرق قرابة 23 دقيقة.',
    explanation: 'مخك مبيعملش «Multitasking» حقيقي، ده بيعمل «تبديل سريع» بيحرق الجلوكوز وبيزود الأخطاء. ساعة تركيز بموبايل في أوضة تانية تساوي 3 ساعات جنبه.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Human_multitasking',
  ),
  Fact(
    id: 117,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الحنين للماضي (النوستالجيا) مش ضعف بل مسكن نفسي طبيعي',
    body: 'تُظهر الدراسات إن استرجاع ذكريات دافئة من الماضي بيرفع التفاؤل والشعور بالانتماء وبيدفي الإنسان نفسيًا وقت الوحدة والضغط.',
    explanation: 'لما الدنيا تضغط عليك، تقليب صور حلوة أو حكايات قديمة مع أهل أو صحاب بيفكرك إن عندك جذور وشبكة أمان.',
