  ),
  Fact(
    id: 118,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «براتفال»: الغلطة الصغيرة البريئة بتخلي الناجح أكتر جاذبية',
    body: 'في تجربة لإليوت أرونسون، أحب المشاركون الشخص الكفء الذي سكب قهوته بالخطأ أكثر من الشخص الكفء «المثالي» الخالي من الأخطاء.',
    explanation: 'المثالية المبالغ فيها بتخلي الناس تحس بمسافة وبرودة، أما العفوية والاعتراف بغلطات بسيطة فبيبين إنك إنسان حقيقي قريب للقلب.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Pratfall_effect',
  ),
  Fact(
    id: 119,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مخك مبيفرقش أوي بين رفض الناس وبين الألم الجسدي في استجابته الأولية',
    body: 'أظهرت فحوصات الرنين المغناطيسي أن الرفض الاجتماعي أو التجاهل ينشّط مناطق دماغية مشابهة لتلك التي تنشط عند الألم الجسدي.',
    explanation: 'عشان كده كلمة جرحت قلبك ممكن توجعك حقيقي وتقفل شهيتك. تذكّر ده يخليك أرفق بكلامك مع غيرك وأكثر تفهمًا لوجعك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Social_rejection',
  ),
  Fact(
    id: 120,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الحلول الإبداعية غالبًا بتيجي في الحمام أو المشي مش وأنت محدّق في الشاشة',
    body: 'عند القيام بنشاط روتيني كالمشي أو الاستحمام، ينشط «تأثير الحضانة» وشبكة الوضع الافتراضي في الدماغ لربط الأفكار البعيدة.',
    explanation: 'لما تعطل قدام مشكلة، ابعد عن المكتب 15 دقيقة وامشِ من غير بودكاست؛ عقلك الباطن هيكمل التوصيل لوحده.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Incubation_(psychology)',
  ),
  Fact(
    id: 121,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'عقلية النمو (Growth Mindset) بتضاعف مرونة التعامل مع الفشل',
    body: 'فرّقت كارول دويك بين من يرى الذكاء ثابتًا (عقلية ثابتة) ومن يراه عضلة تنمو بالتمرين (عقلية النمو)، والفرق بينهما حاسم في التعلم.',
    explanation: 'بدل «أنا فاشل في الإنجليزي» قول «أنا لسه ما أتقنتش الإنجليزي لحد دلوقتي». كلمة «لسه» بتفتح باب التطوير بدل قفلته.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Mindset',
  ),
  Fact(
    id: 122,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير النهاية والذروة: بنفتكر القصة من ذروتها وآخر لحظة فيها',
    body: 'اكتشف دانيال كانيمان أن تقييمنا لأي تجربة يعتمد بشدة على أشد لحظة فيها (الذروة) وكيف انتهت (النهاية)، لا على متوسط كل دقيقة.',
    explanation: 'عشان كده نهاية أي مقابلة عمل، أو مكالمة مع شخص غالي، أو رحلة، هي اللي بتطبع الذكرى الأكبر في الذاكرة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Peak%E2%80%93end_rule',
  ),
  Fact(
    id: 123,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: '«المرآة الاجتماعية»: الناس بترجعلك نفس نظرتك وتوقعاتك غير المعلنة',
    body: 'تميل لغة الجسد الدقيقة (الابتسامة، نبرة الصوت، تواصل العين) إلى توليد استجابة مطابقة تلقائيًا لدى الطرف الآخر عبر الخلايا العصبية المرآتية.',
    explanation: 'لو دخلت أوضة وأنت متوقع الناس تتقبلك وابتسمت بهدوء، نسبة إنهم يبادلوك نفس الدفء بتزيد بشكل حقيقي.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Mirror_neuron',
  ),
  Fact(
    id: 124,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الوهم التوضيحي: لو شرحت فكرة لحد هتكشف إنك مكنتش فاهمها كامل',
    body: 'نظن أننا نفهم الأشياء اليومية كالسحّاب أو الدراجة جيدًا، حتى يُطلب منا شرح طريقة عملها خطوة بخطوة، وتُسمى الظاهرة «وهم العمق التفسيري».',
    explanation: 'اختبار «فاينمان» للتعلم بيقول: اشرح اللي ذاكرته كأنك بتكلمه لطفل 12 سنة. الحتة اللي هتتهته فيها هي دي الحتة اللي محتاج تفهمها تاني.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Illusion_of_explanatory_depth',
  ),
  Fact(
    id: 125,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'سماع اسمك في عز الدوشة (تأثير حفلة الكوكتيل)',
    body: 'رغم انشغالك بحديث وسط ضوضاء عالية، يلتقط دماغك فورًا ذكر اسمك من طرف الغرفة الآخر لأن نظام الترشيح الدماغي يراقبه لاشعوريًا.',
    explanation: 'وعلى نفس المبدأ، نداء الشخص باسمه الأول بلطف في الحوار بيخلي انتباهه ومودته ليك أعلى بوضوح.',
