  ),
  Fact(
    id: 126,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'العصبية بتفقدك 20 دقيقة قرار غلط، والهدوء بينقذك بقوة الصمت 6 ثوانٍ',
    body: 'ذروة التدفق الكيميائي للغضب أو الخوف (الأدرينالين) في الاستجابة الحادة تستغرق بضع ثوانٍ قبل أن تهدأ الموجة الأولى لو لم نغذّها بأفكار غاضبة.',
    explanation: 'لما تتعصب، عد 6 أو 10 ثوانٍ وتنفّس ببطء قبل ما ترد أو تبعت رسالة. الثواني دي هي اللي بتفرق بين رد محترم وندم طويل.',
