  Fact(
    id: 127,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «التقليص» أو التدرج السهل (Foot-in-the-door)',
    body: 'من يوافق على طلب صغير جدًا وبسيط يكون أكثر قابلية نفسيًا للموافقة لاحقًا على طلب أكبر من نفس النوع للحفاظ على اتساق صورته الذاتية.',
    explanation: 'في التطوير الذاتي، طبّقها على نفسك: لما تتفق مع نفسك على 5 دقائق تمرين أو كتابة، انت بتفتح الباب لدخل أكبر بسلاسة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Foot-in-the-door_technique',
  ),
  Fact(
    id: 128,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الإنصات التفاعلي نادر جدًا لدرجة إن المستمع الحقيقي بيظهر كأنه ساحر',
    body: 'في معظم الحوارات لا ينتظر المستمع فهم المتحدث، بل ينتظر دوره في الكلام أو يحضّر ردًا جاهزًا في ذهنه.',
    explanation: 'جرب تسأل اللي قدامك سؤال متابعة بسيط زي «وحسيت بإيه ساعتها؟» من غير ما تحكي قصتك فورًا؛ هتبني ثقة في دقايق بتتأخر سنين عند غيرك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Active_listening',
  ),
  Fact(
    id: 129,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تحيز البقاء (Survivorship Bias): بنشوف اللي نجحوا بس وبننسى اللي وقعوا',
    body: 'عند دراسة الناجحين أو المشاريع المزدهرة، نركّز على قصص النجاح المرئية ونهمل آلاف المحاولات المماثلة التي فشلت ولم يُسمع عنها.',
    explanation: 'قبل ما تقلد قصة «ترك الجامعة وبقى ملياردير»، بص على إحصائيات اللي سابوا الدراسة وفشلوا؛ ده يخليك تخطط بذكاء وأمان.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Survivorship_bias',
  ),
  Fact(
    id: 130,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تعب القرارات (Decision Fatigue) بيزود قراراتنا الغلط آخر اليوم',
    body: 'أشارت دراسات نفسية إلى أن تتابع عشرات القرارات اليومية يستنزف طاقة ضبط النفس، فيميل الإنسان آخر اليوم للتأجيل أو الاختيارات الأسهل.',
    explanation: 'عشان كده تثبيت روتين صباحي بسيط (لبس، فطار، وقت شغل ثابت) بيوفر طاقتك الذهنية للقرارات المهمة فعلًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Decision_fatigue',
  ),
  Fact(
    id: 131,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير التوافر: بنخاف من الطيارة أكتر من العربية رغم إنها آمن بكتير',
    body: 'يحكم العقل على احتمالية وقوع حدث ما بمدى سهولة استدعاء أمثلة له من الذاكرة، لا بالإحصاء الفعلي، وهو «استدلال التوافر».',
    explanation: 'لأن حوادث الطيارات بتتصدر الأخبار، بنخاف منها رغم إن حوادث السيارات أكتر بمئات المرات. فكّر بالأرقام قبل ما تخاف من عنوان مثير.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Availability_heuristic',
  ),
  Fact(
    id: 132,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الإيثار ومساعدة الآخرين بيطيل الصحة النفسية ويقلل التوتر',
    body: 'يرتبط العمل التطوعي وتقديم العون للآخرين بانخفاض مستويات الكورتيزول وارتفاع مشاعر المعنى والسعادة المستقرة (Eudaimonia).',
    explanation: 'لما بتسعد غيرك أو تفرّج كربة عن شخص، مخك بيفرز أوكسيتوسين وإندورفين؛ يعني العطاء مش بس بيساعد غيرك، ده بيعالجك أنت كمان.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Altruism',
  ),
  Fact(
    id: 133,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مخاوفنا في 85% من الأوقات ما بتحصلش أصلًا',
    body: 'في دراسات تتبعت القلق اليومي للناس، تبيّن أن النسبة العظمى من السيناريوهات الكارثية التي يخشاها الشخص لا تقع، وإذا وقع شيء فإننا نتعامل معه أفضل مما توقعنا.',
    explanation: 'مخك مبرمج يحميك من الخطر فبيألف أفلام رعب للمستقبل. لما تقلق، اسأل نفسك: «لو أسوأ حاجة حصلت، إيه أول تصرف هعمله؟» وبس.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Worry',
  ),
  Fact(
    id: 134,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الصمت المريح في العلاقة علامة أمان مش جفاف',
    body: 'تتطلب العلاقات السطحية ملء كل ثانية بالكلام لتخفيف التوتر، بينما يشعر المقربون بالارتياح حتى في فترات الصمت المشترك.',
    explanation: 'لو قدرت تقعد مع شريك حياتك أو صاحبك في هدوء من غير ما تحس بضغط إنك لازم تخترع كلام، فده مؤشر على أمان نفسي عميق.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Interpersonal_relationship',
  ),
  Fact(
    id: 135,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'قاعدة الـ 10-10-10 لاتخاذ القرارات الصعبة من غير تهور',
    body: 'تساعدك قاعدة الـ 10-10-10 على تقييم القرار بسؤال: كيف سأشعر حياله بعد 10 دقائق، وبعد 10 أشهر، وبعد 10 سنوات؟',
    explanation: 'المتعة السريعة بتبان حلوة في الـ 10 دقايق الجايين وبتوجع بعد 10 شهور، أما القرارات الصعبة الشجاعة فبتتعبك دقايق وتبني حياتك للـ 10 سنين.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Decision-making',
  ),
  Fact(
    id: 136,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'المقارنة الاجتماعية الصاعدة على السوشيال ميديا بتسرق رضاك في صمت',
    body: 'يميل دماغنا لمقارنة كواليس حياتنا المليئة بالتعب والمحاولات بـ «لقطات الذروة» الممنتجة في حياة الآخرين.',
    explanation: 'قارن نفسك النهارده بنسخة نفسك من سنة فاتت بس؛ ده المقياس الوحيد العادل اللي ظروفه متطابقة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Social_comparison_theory',
  ),
  Fact(
    id: 137,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تجربة المارشملو الحديثة: الثقة في البيئة بتأثر زي قوة الإرادة',
    body: 'أظهرت إعادة دراسة تجربة المارشملو الشهيرة إن قدرة الطفل على الصبر وتأجيل المكافأة لا تعتمد فقط على قوة الإرادة، بل على ثقته في إن الكبار هيوفوا بوعدهم.',
    explanation: 'عشان كده الالتزام بوعودك البسيطة مع أولادك ومع نفسك بيبني قدرة حقيقية على الصبر والتخطيط للمستقبل.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Stanford_marshmallow_experiment',
  ),
  Fact(
    id: 138,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تحيز التأكيد: مخك بيدوّر على اللي يثبت إنك صح مش على الحقيقة',
    body: 'نبحث لاشعوريًا عن المعلومات التي تؤيد قناعاتنا المسبقة ونتجاهل أو ننتقد الأدلة المخالفة لها، وهو «الانحياز التأكيدي».',
    explanation: 'التدريب الأرقى للعقل إنك قبل ما تحكم في خلاف أو فكرة جديدة، تسأل نفسك بصدق: «إيه الدليل اللي ممكن يثبت إن كلام الطرف التاني صح؟»',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Confirmation_bias',
  ),
  Fact(
    id: 139,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: '«الطفل المشغول» ومقاومة الجهد غير العقلاني (تجارب التوازن النفسي)',
    body: 'الراحة المفرطة والفراغ التام لا يصنعان السعادة كما نظن؛ بل يميل الإنسان لإحساس الإنجاز عند خوض تحدٍ هادف ثم نيل الراحة بعده.',
    explanation: 'كوباية الشاي بعد ساعة شغل متعب طعمها أحلى بكتير من قاعدة يوم كامل من غير هدف.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Idleness_aversion',
  ),
  Fact(
    id: 140,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'السمعة الأولى تتكوّن في عُشر الثانية لكن تغييرها بياخد شهور',
    body: 'أوضحت تجارب برينستون أن الدماغ يكوّن انطباعًا أوليًا عن الثقة والكفاءة في وجه شخص خلال نحو 100 مللي ثانية (عُشر ثانية)، وهو «تأثير الهالة».',
    explanation: 'التفاصيل الصغيرة في أول لقاء — نبرة هادية، نظافة، ابتسامة صادقة — بتفضل شغالة لصالحك فترة طويلة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Halo_effect',
  ),
  Fact(
    id: 141,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الاعتراف بجهلك أو غلطتك بهدوء بيزود احترام الناس ليك مش بيقلله',
    body: 'على عكس الخوف الشائع، يربط الناس بين قول «لا أعرف، سأتأكد» أو «أخطأت» وبين النضج والثقة بالنفس وعدم التظاهر.',
    explanation: 'الهبد أو الدفاع الأعمى عن الغلطة بيكلفك مصداقيتك، بينما الاعتذار الواضح أو طلب التوضيح بيقفل الباب للجدل وبيفتح باب الثقة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Intellectual_humility',
  ),
  Fact(
    id: 142,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الامتنان اليومي بيغير كيمياء النظرة للأحداث خلال 3 أسابيع',
    body: 'كتابة 3 نعم بسيطة يوميًا بانتظام بتعيد تدريب «نظام التنشيط الشبكي» في الدماغ على التقاط الفرص والإيجابيات بدل التركيز على التهديدات.',
    explanation: 'العين بتشوف اللي بتتعود تدور عليه؛ لما تدرب مخك يلاحظ لحظة كرم أو ضحكة أو رزق صغير كل يوم، مزاجك العام بيتحسن تلقائيًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Gratitude',
  ),
  Fact(
    id: 143,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'نظرية «النوافذ المحطمة» في حياتك ومكتبك',
    body: 'تشير نظرية النوافذ المحطمة إلى أن ترك فوضى صغيرة دون إصلاح يشجع نفسيًا على إهمال أكبر حولها، سواء في الشارع أو في روتينك الشخصي.',
    explanation: 'تطبيق بسيط: سرير مترتب ومكتب نضيف الصبح بيخلي مخك أميل للانضباط في باقي اليوم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Broken_windows_theory',
  ),
  Fact(
    id: 144,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'استخدام «لغة نحن» بدل «أنت دايمًا» بينهي نص الخناقة قبل ما تبدأ',
    body: 'الجمل اللي بتبدأ بـ «أنت دايمًا بتعمل كذا» بتفعل دفاعية الطرف التاني فورًا، بينما صيغة «أنا بحس بكذا لما يحصل كذا» بتفتح حوارًا.',
    explanation: 'التعميمات زي «دايمًا» و«أبدًا» بتحوّل الخلاف على موقف معين لمحاكمة للشخص كله؛ ركّز على الموقف المحدد عشان يتحل.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Nonviolent_Communication',
  ),
  Fact(
    id: 145,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مبدأ «عدم التوقع» مش معناه التشاؤم بل الاستعداد الهادئ',
    body: 'في الفلسفة الرواقية (Stoicism)، تمرين «تصور الصعوبات مسبقًا» يقلل صدمة الأزمات لأن الدماغ يكون قد هيّأ خطة بديلة.',
    explanation: 'تقبّل إن اليوم ممكن يكون فيه مطب مروري أو عميل متعب بيخليك تعدّيه بابتسامة بدل ما تنهار عصبيًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Stoicism',
  ),
  Fact(
    id: 146,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'ظاهرة «التنقل العاطفي» (Emotional Contagion): المزاج معدي',
    body: 'ينقل الإنسان مشاعره من توتر أو بهجة إلى من يجالسهم في دقائق عبر تقليد لاواعٍ لتعبيرات الوجه ونبرة الصوت.',
    explanation: 'اختيار صحبتك مش رفاهية؛ قعدتك مع ناس بتتذمر طول الوقت بتسحب طاقتك حتى لو أنت ساكت، وقعدتك مع متفائل هادي بترفعك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Emotional_contagion',
  ),
  Fact(
    id: 147,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الانتماء للقبيلة والخطأ المشترك (تجربة آش للمطابقة)',
    body: 'في تجارب سولومون آش، وافق 75% من المشاركين مرة واحدة على الأقل على إجابة خاطئة واضحة فقط لأن باقي المجموعة اتفقت عليها.',
    explanation: 'الدرس: ضغط الجماعة قوي جدًا؛ احتفظ بمساحة تفكير مستقلة حتى لو رأي الأغلبية في القعدة أو السوشيال ميديا ماشي في اتجاه واحد.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Asch_conformity_experiments',
  ),
  Fact(
    id: 148,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'عقلية الندرة بتقلل الذكاء المؤقت تحت ضغط الفلوس أو الوقت',
    body: 'أثبت باحثون مثل سيندهيل مولايناثان أن الشعور الشديد بندرة المال أو الوقت يستهلك «النطاق الترددي الذهني»، فيبدو الشخص أقل حكمة في قراراته.',
    explanation: 'لما تكون مضغوط ماليًا أو متأخر جدًا، تجنّب تاخد قرارات مصيرية في اللحظة دي؛ هدّي نفسك الأول عشان مساحة تركيزك ترجع.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Scarcity_(social_psychology)',
  ),
  Fact(
    id: 149,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'النقاش لتعديل رأي شخص عنيد بيشتغل عكسي بالهجوم (تأثير الارتداد)',
    body: 'مواجهة معتقد راسخ عند شخص بالهجوم والسخرية قد تدفعه للتمسك به أكثر لحماية هويته الذاتية، لا لتغييره.',
    explanation: 'طرح أسئلة فضولية هادية زي «كيف وصلت للفكرة دي؟» بيخلي الشخص نفسه يراجع تفاصيل حجته بدون ما يحس إنه مهزوم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Belief_perseverance',
  ),
  Fact(
    id: 150,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «التأطير» (Framing): نفس المعلومة بتتغير حسب طريقة تقديمها',
    body: 'يفضّل الناس عبارة «منتج خالٍ من الدهون بنسبة 90%» على عبارة «يحتوي على 10% دهون» رغم تطابق المعنى تمامًا.',
    explanation: 'الطريقة اللي بتكلم بيها نفسك والناس بتغير القرار: بدل «أنا مضطر أروح الجيم» جرب «أنا محظوظ إني هتحرك وأقوي جسمي النهارده».',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Framing_effect_(psychology)',
  ),
  Fact(
    id: 151,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير التباعد الزمني: ليه بنوعد نفسنا للـ «أسبوع الجاي» بسهولة؟',
    body: 'نتعامل مع «نسخة نفسنا في المستقبل» في فحوصات الدماغ وكأنها شخص غريب، ولذلك نحمّلها ديونًا ومهام صعبة بلا رحمة.',
    explanation: 'تخيل نفسك بعد أسبوع كأنه أعز صديق ليك: هل كنت هترضى تسيبه يشيل كل التراكم ده لوحده؟ لو لأ، ابدأ جزء بسيط النهارده.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Hyperbolic_discounting',
  ),
  Fact(
    id: 152,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الكتابة اليدوية بتحفز الذاكرة والفهم أعمق من الكيبورد',
    body: 'أظهرت أبحاث نفسية أن تدوين الملاحظات باليد يجبر الدماغ على تلخيص المعاني وفهمها بدل النسخ الحرفي السريع على لوحة المفاتيح.',
    explanation: 'لما تقرأ كتاب أو تحضر كورس مهم، لخّص أهم 3 أفكار بخط إيدك في نوتة؛ هتثبت في دماغك أضعاف.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Note-taking',
  ),
  Fact(
    id: 153,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'أسلوب التعلّق (Attachment Style) في الطفولة بيشكّل علاقاتك وأنت كبير',
    body: 'أظهر جون بولبي وماري أينسورث أن أنماط التعلق في الطفولة (الآمن، القلق، المتجنب) تنعكس لاحقًا في طريقة تعاملنا مع القرب والخصام.',
    explanation: 'الخبر الحلو إن نمط التعلق مش قدر ثابت؛ بالوعي والعلاقات الصحية تقدر تتحول تدريجيًا لنمط تعلق آمن وناضج.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Attachment_theory',
  ),
  Fact(
    id: 154,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: '«تأثير الجيل» (Generation Effect): المعلومة اللي بتستنتجها بتثبت أكتر',
    body: 'يتذكر الدماغ المعلومة التي شارك في توليدها أو استنتاجها أو الإجابة عن سؤال عنها أفضل بكثير من المعلومة التي قرأها جاهزة.',
    explanation: 'عشان كده وأنت بتذاكر أو بتقرأ، قفل الكتاب واسأل نفسك: «إيه اللي افتكرته؟» أفضل من إنك تعيد قراءة الصفحة 5 مرات.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Generation_effect',
  ),
  Fact(
    id: 155,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'قاعدة الـ 1% يوميًا: التحسن الصغير بيتراكم زي الفايدة المركبة',
    body: 'تحسن مهارة بنسبة 1% يوميًا لمدة عام لا يعطي 365% فقط، بل يعطي رياضيًا 1.01 أس 365 أي حوالي 37.7 ضعفًا.',
    explanation: 'السر مش في الحماس الجبار يومين وتبطيل شهر، السر في خطوة صغيرة مستمرة حتى في الأيام اللي مالكش مزاج فيها.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Kaizen',
  ),
  Fact(
    id: 156,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الصداقات القوية ليها أثر صحي يعادل الإقلاع عن التدخين في الدراسات الطويلة',
    body: 'خلصت دراسة هارفارد الممتدة لأكثر من 80 عامًا حول السعادة إلى أن جودة العلاقات القريبة هي أقوى مؤشر على طول العمر والصحة النفسية والجسدية.',
    explanation: 'المنصب والفلوس مهمين لتلبية الاحتياجات، لكن في النهاية الشخص اللي تقدر تتصل بيه الساعة 3 الفجر وأنت متضايق هو ثروتك الحقيقية.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Grant_Study',
  ),
  Fact(
    id: 157,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مغالطة التخطيط (Planning Fallacy): بنقدّر الوقت أقل من الحقيقة بكتير',
    body: 'يميل البشر للتفاؤل المفرط عند تقدير زمن إنجاز مهامهم، متجاهلين العوائق غير المتوقعة التي حدثت في مشاريعهم السابقة.',
    explanation: 'قاعدة عملية: بعد ما تحسب إن المشوار أو الشغلانة هتاخد ساعة، اضرب في 1.5 أو ضيف ربع ساعة احتياط عشان تعيش بدون لهوجة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Planning_fallacy',
  ),
  Fact(
    id: 158,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'التعاطف مع الذات أقوى من جلد الذات في تعديل السلوك',
    body: 'أثبتت أبحاث كريستين نيف أن جلد النفس بعد الغلط يزيد التوتر ويدفع للتسويف، بينما اللطف مع النفس يشجع على التصحيح والمحاولة.',
    explanation: 'كلم نفسك لما تغلط بنفس الطريقة اللي بتشجع بيها صاحبك المقرب لو وقع في نفس الغلطة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Self-compassion',
  ),
  Fact(
    id: 159,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'البيئة أقوى من قوة الإرادة في 9 من أصل 10 مرات',
    body: 'تظهر أبحاث تصميم السلوك أن الأشخاص الأكثر «انضباطًا» ليسوا أصحاب إرادة خارقة، بل صمموا بيئتهم لتقل فيها الإغراءات والمشتتات.',
    explanation: 'بدل ما تحارب شهوة الشوكولاتة أو الموبايل بقوة الإرادة، شيلهم من قدام عينك وحط كتاب أو تفاحة مكانهم.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Nudge_theory',
  ),
  Fact(
    id: 160,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'سؤال «لماذا؟» ساعات بيزود الاكتئاب، وسؤال «إيه الخطوة؟» بيحرر المخ',
    body: 'الاجترار الذهني بأسلوب «ليه دايمًا بيحصل لي كده؟» يغلق الدماغ في دائرة عجز، بينما التحول لـ «إزاي أتعامل مع الموقف دلوقتي؟» ينشّط حل المشكلات.',
    explanation: 'استبدل «ليه أنا؟» بـ «ما الدرس وما الخطوة؟» — سؤال واحد يقدر يبدل مسار يوم كامل.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Rumination_(psychology)',
  ),
  Fact(
    id: 161,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير الترسانة المعرفية: تعدد الأدوار بيحميك من الصدمات',
    body: 'الأشخاص الذين يستثمرون هويتهم في عدة دوائر (شغل، أسرة، هواية، رياضة، تطوع) يتعافون أسرع عند اهتزاز إحدى تلك الدوائر.',
    explanation: 'ما تحطش كل قيمتك في سلة واحدة زي الشغل أو شخص واحد؛ التنوّع بيدي توازن نفسي يحميك من السقوط لو باب اتقفل.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Self-complexity',
  ),
  Fact(
    id: 162,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الضحك الحقيقي المعدي بيبني ثقة فورية في المجموعات',
    body: 'ينتج الضحك المشترك إفرازات إندورفين تقوّي الروابط الاجتماعية وتكسر الحواجز الهرمية أسرع من المحاضرات والاجتماعات الرسمية.',
    explanation: 'خفة الدم المحترمة في وقتها بتخلي الفريق أهدى وأكثر إبداعًا وقدرة على تخطي الضغط.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Laughter',
  ),
  Fact(
    id: 163,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير المرساة (Anchoring): أول رقم بتسمعه في المفاوضات بيتحكم فيك',
    body: 'في علم النفس الاقتصادي، يؤثر أول رقم يُطرح على الطاولة (المرساة) بشدة على تقدير الطرفين للسعر العادل حتى لو كان الرقم عشوائيًا.',
    explanation: 'في البيع والشراء أو مفاوضات الراتب، لو عارف القيمة الحقيقية ابدأ بطرح رقم مرجعي مدروس عشان تظبط بوصلة النقاش.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Anchoring_effect',
  ),
  Fact(
    id: 164,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مفارقة التفرّد: الكل عايز يبقى مميز وبيلبس زي بعضه في الآخر',
    body: 'يسعى البشر للتعبير عن فرديتهم، لكنهم يلتزمون بمعايير مجموعتهم الاجتماعية لتجنب الرفض، فينتج عن ذلك تشابه غير مقصود.',
    explanation: 'النضج الحقيقي هو إنك تختار قيمك وأسلوبك بما يناسب حياتك وقناعاتك، لا لمجرد المخالفة ولا لمجرد التقليد الأعمى.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Optimal_distinctiveness_theory',
  ),
  Fact(
    id: 165,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الهدوء والملل الصحي ضروريين لنمو الإبداع عند الكبار والأطفال',
    body: 'قتل كل لحظة انتظار أو ملل بتصفح الهاتف يمنع الدماغ من الدخول في «أحلام اليقظة البناءة» التي تولد منها الأفكار الجديدة.',
    explanation: 'جرب تقف في طابور أو تركب مواصلة 10 دقايق من غير ما تفتح الموبايل؛ هتتفاجئ بكمية الأفكار والحلول اللي هتطلع في دماغك.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Default_mode_network',
  ),
  Fact(
    id: 166,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'المساعدة المتأخرة أو «قانون المتفرج»: كل ما الناس تكتر، اللي بيساعد يقل',
    body: 'في ظاهرة «تأثير المتفرج» (Bystander Effect)، تقل احتمالية تدخل الفرد لمساعدة شخص في أزمة كلما زاد عدد المتفرجين حوله بسبب تشتت المسؤولية.',
    explanation: 'لو حصل لك طارئ في الشارع، ما تصرخش «حد يساعدني!»، شاور على شخص واحد بعينه: «أنت يا اللي لابس قميص أزرق اطلب الإسعاف!» — فكّ التشتت فورًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Bystander_effect',
  ),
  Fact(
    id: 167,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'عقلنا بيملأ الفراغات بتأليف قصص وهمية لما تغيب المعلومة',
    body: 'عندما يرسل شخص رسالة مقتضبة أو يتأخر عن الرد، يميل دماغنا لملء الفراغ بأكثر قصة درامية أو سلبية متوافقة مع مخاوفنا.',
    explanation: 'افتراض حسن النية أو التأكد المباشر بسؤال لطيف بيوفر عليك ساعات من الحرق الذهني على سيناريو محصلش أصلًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Cognitive_distortion',
  ),
  Fact(
    id: 168,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'التمثيل المبهج أحيانًا بيجر المشاعر وراه (فرضية التغذية الوجهية)',
    body: 'تشير أبحاث علم النفس الانفعالي إلى أن تعبيرات الوجه ووضعية الجسد المستقيمة لا تعبّر عن المزاج فقط، بل ترسل إشارات عصبية تعيد تعديله قليلًا.',
    explanation: 'فرد ضهرك وأنت شغال أو ابتسامة خفيفة وقت التوتر بتبعت رسالة أمان هادية لجهازك العصبي.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Facial_feedback_hypothesis',
  ),
  Fact(
    id: 169,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'قاعدة الخمس ثوانٍ لكسر تردد البدء',
    body: 'تأخير تنفيذ قرار إيجابي لأكثر من 5 ثوانٍ يسمح لقشرة الدماغ بإنتاج عشرات الأعذار لإبقائك في منطقة الراحة.',
    explanation: 'أول ما يجي في بالك تقوم تصلي أو تبدأ شغل أو تكلم شخص غالي، عد 5-4-3-2-1 واتحرك جسديًا قبل ما مخك يفتح باب الأعذار.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Action_bias',
  ),
  Fact(
    id: 170,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'الإيجابية السامة بتزود الألم النفسي بدل ما تخففه',
    body: 'إجبار النفس أو الآخرين على الابتسام وتجاهل الحزن بعبارات مثل «فرفش كل حاجة هتبقى تمام» يؤدي لكبت المشاعر وتأخر التعافي.',
    explanation: 'التوازن الصحي إنك تعترف بالوجع وتدي لنفسك حقها في الزعل شوية، وفي نفس الوقت تحتفظ بالأمل والخطوة الجاية.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Toxic_positivity',
  ),
  Fact(
    id: 171,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: '«الحدود الصحية» بتحمي المحبة مش بتقطعها',
    body: 'القدرة على قول «لأ» بلطف ووضوح تمنع تراكم الاستياء الخفي وتبقي العلاقات صادقة ومستمرة على المدى الطويل.',
    explanation: 'لما توافق على حاجة فوق طاقتك وأنت متضايق، أنت بتشتري رضا لحظي بسعر الغضب لاحقًا؛ اللطف والوضوح معًا هما الاحترام الحقيقي.',
