  ),
  Fact(
    id: 172,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'العطلة القصيرة المتكررة بتدي سعادة أكبر من إجازة طويلة واحدة كل سنة',
    body: 'نظرًا للتكيف السريع، تتراجع ذروة متعة السفر أو الإجازة بعد الأيام الأولى، فتوزيع أيام الراحة على فترات متقاربة يجدد النشاط أكثر.',
    explanation: 'استراحة نص يوم أو رحلة قصيرة كل شهرين بتشحن بطاريتك النفسية أحسن من استنزاف نفسك 11 شهرًا انتظارًا لأسبوعين.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Vacation',
  ),
  Fact(
    id: 173,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «رؤية التقدم»: أصغر إنجاز مرئي هو أكبر وقود للحماس اليومي',
    body: 'حلّلت تيريزا أمابيل آلاف اليوميات لموظفين ووجدت أن أقوى محفز للمزاج والإنتاجية لم يكن المكافأة المالية بل «الشعور بالتقدم» في عمل ذي معنى.',
    explanation: 'اعمل لنفسك قائمة إنجازات صغيرة تشطب عليها كل يوم؛ علامة الصح دي بتدي مخك جرعة دوبامين نظيفة تشجعك تكمل.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Motivation',
  ),
  Fact(
    id: 174,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مخك بيتعلم بالراحات القصيرة (التكرار المتباعد) 3 أضعاف الحفظ المتواصل',
    body: 'مراجعة المعلومة على فترات متباعدة (يوم، 3 أيام، أسبوع) تبني مسارات عصبية أمتن بكثير من المذاكرة المكثفة في ليلة واحدة.',
    explanation: 'نظام 20 دقيقة يوميًا لتعلم لغة أو حفظ معلومة بيغلب بسهولة نظام 5 ساعات مرة واحدة في الأسبوع.',
    sourceName: 'Wikipedia',
