  ),
  Fact(
    id: 175,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'لغات الحب الخمس مش مجرد شعار بل خريطة لفهم سوء التفاهم',
    body: 'يختلف الناس في الطريقة الأساسية التي يشعرون بها بالتقدير: الكلمات، الوقت الجيد، الهدايا، أفعال الخدمة، أو التلامس الجسدي.',
    explanation: 'كتير من الخلافات بتحصل لأن طرف بيقدم حب بطريقة «أفعال الخدمة» وهو منتظر «كلمة حلوة»، فافهم لغة شريكك عشان مجهودك يوصل لقلبه.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/The_Five_Love_Languages',
  ),
  Fact(
    id: 176,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «ملاحظة الفوربس» أو القفزة الخاطئة: التنوع الثقافي يزيد الإبداع',
    body: 'الاحتكاك بخلفيات وثقافات وأفكار مختلفة عن دائرتك المعتادة يجبر الدماغ على الخروج من القوالب الجاهزة وإنتاج حلول أصلية.',
    explanation: 'اقرأ في مجال بعيد عن تخصصك مرة في الأسبوع؛ أفكار الطب ساعات بتحل مشاكل البرمجة وأفكار التاريخ بتوضح تحديات البيزنس.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Creativity',
  ),
  Fact(
    id: 177,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تحيز النتيجة (Outcome Bias): الحكم على القرار بالنتيجة بس فخ كبير',
    body: 'نميل للحكم على جودة قرار ما بناءً على نتيجته النهائية فقط، لا على جودة المعلومات والمنطق وقت اتخاذه.',
    explanation: 'ممكن تاخد قرار مدروس ومحترم وتخسر لظرف طارئ، وممكن واحد يتهور ويكسب صدفة. قيّم قراراتك بالمنهج مش بالحظ.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Outcome_bias',
  ),
  Fact(
    id: 178,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تدوين هموم الغد قبل النوم بيساعد على النوم أسرع',
    body: 'أظهرت دراسة أن كتابة قائمة بمهام الغد قبل النوم بـ 5 دقائق تقصّر الوقت اللازم للاستغراق في النوم مقارنةً بكتابة ما أُنجز اليوم.',
    explanation: 'السبب إن المخ بيوقف الدوران على «أوعى تنسى بكرة كذا» لما يشوف إنها متسجلة في أجندة بوضوح.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Sleep_hygiene',
  ),
  Fact(
    id: 179,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تأثير «فقدان القيمة»: الحاجة الممنوعة أو المحدودة بتغري العقل زيادة',
    body: 'عندما يدرك الإنسان أن خيارًا ما على وشك الاختفاء أو ممنوع دون مبرر مقنع، تنشط «المفاعلة النفسية» التي ترفع رغبته فيه.',
    explanation: 'لاحظ الإعلانات اللي بتقول «آخر مقعدين» ولاحظ في تربية الأولاد إن كثرة «ممنوع» من غير شرح بتخلق فضولًا مضاعفًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Reactance_(psychology)',
  ),
  Fact(
    id: 180,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'العمل الجماعي ساعات بيقلل الجهد الفردي (التكاسل الاجتماعي)',
    body: 'يميل الأفراد لبذل جهد أقل عندما يعملون ضمن مجموعة غير محددة الأدوار مقارنةً بعملهم منفردين، وهي ظاهرة «التكاسل الاجتماعي».',
    explanation: 'الحل في أي فريق: توزيع مسؤوليات واضحة لكل اسم بمهام قابلة للقياس، عشان الكل يحس بقيمة دوره الحقيقي.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Social_loafing',
  ),
  Fact(
    id: 181,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'متلازمة «ألفا الدائرة» مش دايمًا الأقوى: الأمان النفسي بيصنع أذكى الفرق',
    body: 'في دراسة مشروع «أرسطو» الشهيرة في غوغل، كان «الأمان النفسي» — حرية طرح سؤال أو الاعتراف بخطأ دون سخرية — أهم عامل لنجاح الفرق.',
    explanation: 'الفريق اللي أفراده مش خايفين يظهروا جهلاء في تفصيلة صغيرة بيكتشف المشاكل بدري وبيبدع أسرع.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Psychological_safety',
  ),
  Fact(
    id: 182,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'مخك بيتفائل للمستقبل بس بينسى حساب الصيانة (وهم التقدير العاطفي)',
    body: 'نبالغ غالبًا في توقع شدة فرحتنا بأحداث مستقبلية كالترقية أو مدة استمرار حزننا بعد خسارة، وهو ما يسمى «خطأ التنبؤ العاطفي».',
    explanation: 'الإنسان عنده «جهاز مناعة نفسي» أذكى بكتير مما يتخيل؛ بتزعل وتتألم، لكنك بترجع تتوازن أسرع مما كنت خايف.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Affective_forecasting',
  ),
  Fact(
    id: 183,
    category: 'نفسية وعلاقات وتطوير ذات',
    title: 'تغيير السياق بالكلمات: «متحمس» بدل «متوتر» بيغير الأداء فعليًا',
    body: 'أثبتت تجارب أليسون وود بروكس أن القلق والحماس يرفعان ضربات القلب بنفس الدرجة، وترديد «أنا متحمس» قبل عرض أو امتحان يحسّن الأداء.',
    explanation: 'بدل ما تحاول تهدي نفسك بالغصب وأنت متوتر، حوّل الطاقة الجسدية دي لحماس: «جسمي بيستعد يدّي أحسن ما عنده».',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Cognitive_reappraisal',
  ),
  Fact(
    id: 184,
    category: 'علوم ورياضيات وعلماء',
    title: 'كلمتا «جبر» و«خوارزمية» جايين من عالم عربي مسلم واحد',
    body: 'مصطلح Algebra مأخوذ من عنوان كتاب محمد بن موسى الخوارزمي «الجبر والمقابلة»، ومصطلح Algorithm مشتق من تحريف اسمه باللاتينية.',
    explanation: 'كل برنامج على موبايلك وكل محرك بحث وملاحة بيشتغل بخوارزميات، واللي أسس المنهج المنهجي ده هو الخوارزمي في بيت الحكمة ببغداد في القرن التاسع.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Al-Khwarizmi',
  ),
  Fact(
    id: 185,
    category: 'علوم ورياضيات وعلماء',
    title: 'الحسن بن الهيثم هو أول من أثبت إن العين بيدخلها الضوء مش بيخرج منها',
    body: 'سادت عند الإغريق فكرة إن العين تخرج أشعة لترى، حتى أثبت الحسن بن الهيثم بالتجربة في كتابه «المناظر» أن الضوء ينعكس من الأجسام ويدخل العين.',
