    title: 'غريس هوبر عثرت على أول «Bug» برمجي حقيقي: فراشة جوه الكمبيوتر',
    body: 'عام 1947 في هارفارد، توقف كمبيوتر Mark II بسبب عثة (فراشة صغيرة) محشورة بين نقاط التلامس، فلصقها فريق غريس هوبر في السجل وسمّوها Bug.',
    explanation: 'رغم إن كلمة Bug كانت مستخدمة في الهندسة قبلها للأعطال، فإن الحادثة دي خلت مصطلح Debugging (تنظيف الأكواد من البق) شهيرًا في عالم البرمجة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Grace_Hopper',
  ),
  Fact(
    id: 212,
    category: 'علوم ورياضيات وعلماء',
    title: 'الإسفنج والمياه العميقة؟ لا، بل عسل النحل السليم لا يفسد لآلاف السنين',
    body: 'اكتشف علماء الآثار أواني عسل نحل داخل مقابر فرعونية مصرية يعود عمرها لنحو 3000 سنة ولا يزال العسل صالحًا غير متعفن.',
    explanation: 'السر في 3 أسلحة طبيعية: نسبة السكر العالية جدًا، قلة الرطوبة، والحموضة الطبيعية مع وجود بيروكسيد الهيدروجين تمنع نمو البكتيريا.',
