    title: 'كوكب أورانوس بيتدحرج في مداره على جنبه مش بيدور زي النحلة',
    body: 'يميل محور دوران كوكب أورانوس بزاوية تقارب 98 درجة، مما يجعله يبدو وكأنه يتدحرج على جانبه حول الشمس.',
