    title: 'أول مبرمجة ساعدت في رحلة أبولو 11 إلى القمر هي مارغريت هاميلتون',
    body: 'قادت مارغريت هاميلتون فريق هندسة البرمجيات لمركبة أبولو، وصممت نظام أولويات أنقذ هبوط أبولو 11 من الإلغاء قبل ملامسة القمر بدقائق.',
    explanation: 'النظام ذكي بحيث تجاهل المهام غير الضرورية وقت الزحمة وركّز على الهبوط بس، وهي اللي ساهمت في ترسيخ مصطلح «هندسة البرمجيات» (Software Engineering).',
