    title: 'الكاكاو؟ لا، الماس ممكن يتعمل من زبدة الفول السوداني في المعمل',
    body: 'بما أن الماس مكون من كربون مضغوط تحت حرارة وضغط هائلين، نجح علماء في تحويل الكربون الموجود في زبدة الفول السوداني إلى بلورات ماس صغيرة.',
    explanation: 'طبعًا الماس الناتج صغير جدًا وتكلفته المعملية غالية، لكنه إثبات ظريف إن تركيب الماس النقي هو كربون 100% زي الفحم بس مترتب في شبكة بلورية فائقة التنظيم.',
