    title: 'أبراج الهوائي والحقيقة عن المطر: ريحة التراب بعد المطر ليها اسم علمي',
    body: 'الرائحة المنعشة التي نشمها عند سقوط المطر على أرض جافة تُسمى «بتريكور» (Petrichor)، وتنتج عن زيوت نباتية ومركب تفرزه بكتيريا التربة.',
    explanation: 'عندما تضرب قطرة المطر التراب تحبس فقاعات هواء صغيرة تخرج للجو وتنقل مركب الـ Geosmin، وأنف الإنسان حساس جدًا لهذه الرائحة بشكل عجيب.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Petrichor',
  ),
  Fact(
    id: 218,
    category: 'علوم ورياضيات وعلماء',
    title: 'لماذا يوجد «قلم رصاص» دون رصاص أصلًا؟',
    body: 'لبّ قلم الرصاص مصنوع من الجرافيت المخلوط بالطين وليس معدن الرصاص السام، وسُمي خطأً لأن مكتشفيه في القرن السادس عشر ظنوه نوعًا من خام الرصاص.',
    explanation: 'حتى اليوم الاسم فضل معلق بالمنتج، بينما لو أكل طفل سن القلم بالخطأ (لا ينصح بذلك طبعًا) فهو كربون نقي غير سام مقارنةً بمعدن الرصاص.',
