    title: 'نظرية الألعاب: أحيانًا «التعاون» بيكسب أكتر من «الأنانية» بالمعادلات',
    body: 'أثبت عالم الرياضيات جون ناش ومعادلات معضلة السجين المتكررة أن التعاون مع استراتيجية «المعاملة بالمثل» يتفوق على الخداع على المدى الطويل.',
