    title: 'الزجاج سائل بطيء؟ خرافة مشهورة والحقيقة إنه «صلب غير متبلور»',
    body: 'يعتقد البعض أن زجاج الكنائس القديمة أسمك من الأسفل لأنه «يسيل» ببطء مع الزمن، لكن الحقيقة إن صناعة الزجاج القديمة هي اللي كانت تنتج ألواحًا غير مستوية.',
