    body: 'في القرن التاسع عشر والنصف الأول من العشرين، كان لقب Computer يُطلق على البشر (وغالبيتهن نساء في المراصد وناسا مثل كاثرين جونسون) الذين يجرون الحسابات المعقدة بالورقة والقلم.',
