    title: 'مفارقة بنفورد: الأرقام الحقيقية في الفواتير والطبيعة بتبدأ بالرقم 1 أكتر بكتير من 9',
    body: 'حسب «قانون بنفورد»، في قوائم البيانات الطبيعية (كعدد سكان المدن أو فواتير الشركات)، يظهر الرقم 1 كأول خانة بنسبة ~30% بينما الرقم 9 بنسبة ~4.6% فقط.',
