    body: 'في 1928 ترك ألكسندر فليمنغ أطباق بكتيريا قبل إجازته، ولما رجع لقى فطر عفن قتل البكتيريا حواليه في أحد الأطباق فاستخلص منه أول مضاد حيوي.',
