    body: 'تحتفظ متاحف بتاريخ «بطارية بغداد» وهي جرة طينية من العصر البارثي بها أسطوانة نحاس وقضيب حديد، ويمكنها نظريًا توليد جهد كهربائي ضعيف عند ملئها بخل أو عصير.',
