    title: 'محيط دائرة الأرض: لو لفيت حبل حول الأرض وزدت طوله متر واحد فقط هيرتفع عن الأرض 16 سم',
    body: 'مفارقة رياضية لطيفة: لو مددت حبلًا على محيط الأرض كلها ثم أضفت مترًا واحدًا فقط لطوله، سيرتفع الحبل بالتساوي 15.9 سم في كل مكان!',
