    title: 'الأعداد الأولية بتستخدمها البنوك لحماية بطاقتك البنكية ومحادثاتك',
    body: 'تعتمد خوارزمية التشفير الشهيرة RSA على حقيقة رياضية: ضرب عددين أوليين ضخمين سهل جدًا، لكن تحليل الناتج لإيجاد العددين الأصليين شبه مستحيل بالحواسيب العادية.',
    explanation: 'فكرة رياضية بحتة اتدرست للمتعة من مئات السنين بقت هي الدرع اللي بيحمي تجارة العالم ورسائل واتساب والبنوك كل ثانية.',
