    title: 'تأثير الفراشة: عالم أرصاد اكتشف الفوضى لما قرّب رقم في الكمبيوتر',
    body: 'عام 1961 أعاد عالم الأرصاد إدوارد لورنز تشغيل محاكاة للطقس بإدخال 0.506 بدل 0.506127 فقط، فانتهت التوقعات لطقس مختلف تمامًا بعد أسابيع.',
    explanation: 'الاكتشاف ده أسس «نظرية الفوضى» (Chaos Theory) وفسّر ليه مستحيل نتنبأ بالطقس بدقة تامة بعد أسبوعين مقدمًا.',
