  ),
  Fact(
    id: 241,
    category: 'علوم ورياضيات وعلماء',
    title: 'إلكترونات جسمك ومقاعدك متلامسوش فعليًا: التنافر هو اللي بيمنعك تقع جوه الأرض',
    body: 'معظم حجم الذرة فراغ هائل، وحين تجلس على كرسي، فإن التنافر الكهرومغناطيسي بين إلكترونات جسمك وإلكترونات الكرسي هو ما يرفعك.',
