    title: 'سُمّي «العصر الذهبي»؟ لا، العالم عمر الخيام كان رياضيًا فذًا قبل ما يكون شاعرًا',
    body: 'قبل قرون من ديكارت، حل عمر الخيام المعادلات التكعيبية هندسيًا بتقاطع القطوع المخروطية، كما شارك في وضع التقويم الجلالي الأدق من الغريغوري وقتها.',
    explanation: 'كتير من الناس يعرفوا الخيام بالرباعيات، لكنه في تاريخ الرياضيات من أعمدة الجبر والهندسة في القرن الحادي عشر.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Omar_Khayyam',
  ),
  Fact(
    id: 263,
    category: 'علوم ورياضيات وعلماء',
    title: 'حشرة بتعرف الطريق بالنجوم ومجرة درب التبانة؟ خنفساء الروث!',
    body: 'اكتشف علماء الأحياء في 2013 أن خنفساء الروث الأفريقية تستخدم ضوء مجرة درب التبانة ليلًا للحفاظ على سيرها في خط مستقيم.',
    explanation: 'لما الدنيا تضلم ومفيش قمر، الخنفساء بترفع راسها للسماء وتستخدم الحزام المضيء للمجرة كبوصلة عشان ماحدش يسرق كورتها!',
