    title: 'في الرياضيات: اللانهاية ليست حجمًا واحدًا، في لانهايات أكبر من لانهايات!',
    body: 'أثبت جورج كانتور في القرن التاسع عشر أن لانهاية الأعداد الحقيقية (العشرية) «أكبر» رياضيًا من لانهاية الأعداد الصحيحة (1، 2، 3...).',
    explanation: 'تقدر تعد الأعداد الصحيحة في قايمة طويلة إلى ما لا نهاية، بس مستحيل تحط كل الأرقام العشرية بين 0 و1 في قايمة حتى لو معاك أبد الآبدين!',
