    body: 'عند التقاء مياه نهر عذب بمحيط مالح أو تيارات بملوحة وحرارة مختلفة، تظل المياه منفصلة بصريًا لمسافات بفعل اختلاف الكثافة والتوتر السطحي قبل الامتزاج التدريجي.',
