    body: 'عام 1945 كان المهندس بيرسي سبنسر يختبر أنبوب رادار (ماغنيترون) فلاحظ أن لوح الشوكولاتة في جيبه ذاب، فجرّب بعده حبوب ذرة اللي اتحولت لفشار في ثوانٍ!',
