    body: 'اكتشف لغويون أن سرعة نقل المعلومات في الكلام متقاربة جدًا بين اللغات: اللغة السريعة المقاطع (كاليابانية والإسبانية) تحمل معلومات أقل في كل مقطع من البطيئة (كالإنجليزية والصينية).',
