    body: 'كشف التصوير بالرنين المغناطيسي الحي أن صوت طقطقة المفاصل ينتج عن تكوّن فجوة غازية سريعة (Cavitation) في السائل الزلالي للمفصل، ولا يسبب التهاب المفاصل.',
    explanation: 'الطبيب دونالد أنغر فرقع أصابع إيده الشمال بس لمدة 60 سنة وساب اليمين للمقارنة وماجالوش أي التهاب مفاصل وفاز بجائزة إيج نوبل على تجربته!',
