    title: 'الدماغ نفسه ما بيحسش بالألم لأنه خالٍ من مستقبلات الألم',
    body: 'رغم أن الدماغ هو المركز الذي يفسّر إشارات الألم من كل الجسم، فإن أنسجة المخ نفسها لا تحتوي على مستقبلات ألم، ولذلك تُجرى أحيانًا جراحات المخ والمريض مستيقظ.',
    explanation: 'أما وجع الصداع فبييجي من الأوعية الدموية والأغشية المحيطة بالمخ وعضلات الرقبة والوجه، مش من خلايا المخ نفسها.',
