    title: 'عدد البكتيريا جوه وعلى جسمك يساوي تقريبًا عدد خلايا جسمك البشرية',
    body: 'تشير التقديرات الحديثة إلى أن جسم الشخص البالغ يحتوي على نحو 30 تريليون خلية بشرية ونحو 38 تريليون خلية بكتيرية نافعة ومتعايشة، معظمها في القولون.',
    explanation: 'الميكروبيوم ده مش عدو، ده شريك بيهضم ألياف ما نقدرش نهضمها وبيصنع فيتامينات زي فيتامين K وبعض فيتامينات B وبيدرب جهازك المناعي.',
