    title: 'أقوى عضلة نسبيًا في الفك؟ عضلة المضغ تقدر تولد قوة ضغط كبيرة على الأضراس',
    body: 'تستطيع عضلة المضغ (Masseter) مع عضلات الفك توليد قوة عضٍّ تتجاوز عشرات الكيلوغرامات على الأضراس الخلفية.',
    explanation: 'أما أقوى عضلة تعمل بلا توقف طول حياتك فهي عضلة القلب اللي بتنبض حوالي 100 ألف مرة كل يوم من غير ما تشتكي.',
