    title: 'أظافرك بتطول أسرع في الإيد اللي بتستخدمها أكتر وفي الصيف أسرع من الشتاء',
    body: 'تنمو أظافر اليدين بمعدل يقارب 3 ملم شهريًا (أسرع من أظافر القدمين بـ 2–3 مرات)، ويزداد النمو قليلًا مع زيادة تدفق الدم والحركة.',
    explanation: 'لاحظ كمان إن الضفر الأوسط في اليد غالبًا بيطول أسرع من ظفر الإبهام والخنصر.',
