    body: 'أثناء النوم العميق، تتقلص المساحات بين خلايا الدماغ لتسمح للسائل النخاعي بغسل المخ من البروتينات المتراكمة والفضلات الاستقلابية.',
    explanation: 'النوم الكافي مش كسل ولا رفاهية؛ ده وقت «النظافة والصيانة اليومية» اللي بيحمي ذاكرتك على المدى البعيد.',
