    body: 'تجعد أصابع اليدين والقدمين بعد النقع في الماء لا يحدث بالانتفاخ البسيط بل باستجابة عصبية إرادية تقلص الأوعية الدموية تحت الجلد لتعمل كأخاديد إطارات السيارات.',
