    body: 'عندما تتكلم، تسمع صوتك بطريقتين: عبر الهواء لأذنك الخارجية وعبر اهتزازات عظام الجمجمة اللي بتزود العمق والجهارة؛ بينما في التسجيل بتسمع مسار الهواء فقط.',
