    body: 'يمثل الجلد نحو 15% من وزن الجسم ويحمي الأعضاء الداخلية من الميكروبات والجفاف، وتتجدد طبقته الخارجية (البشرة) بالكامل كل 28 إلى 40 يومًا تقريبًا.',
