    body: 'تنقسم الدموع إلى دموع قاعدية لترطيب العين، ودموع انعكاسية لطرد البصل أو الغبار، ودموع عاطفية عند الحزن أو الفرح الشديد، وتختلف في تركيبتها الكيميائية.',
