    body: 'أظهرت دراسات الأيض أن المشي الخفيف لمدة 10–15 دقيقة بعد الوجبات الرئيسية يقلل ذروة ارتفاع سكر الدم بشكل ملحوظ لأن العضلات تسحب الجلوكوز فورًا.',
