    body: 'يحتوي القلب على «العقدة الجيبية الأذينية» وهي منظم نبض طبيعي يولد إشارات كهربائية ذاتيًا، لذا يمكنه الاستمرار في الخفقان لفترة وجيزة حتى عند فصله عن الدماغ طالما توفر له الأكسجين.',
