    body: 'تفرز الجيوب الأنفية غاز أكسيد النيتريك عند التنفس من الأنف، وهو يساعد على قتل بعض الجراثيم وتوسيع الأوعية الدموية في الرئتين لتحسين امتصاص الأكسجين.',
