    body: 'يشبه تركيب الكافيين جزيء «الأدينوزين» المسؤول عن النعاس؛ فيقفل مستقبلاته في الدماغ مؤقتًا دون أن يزيل التعب الفعلي أو يصنع طاقة.',
    explanation: 'لما مفعول القهوة يروح، الأدينوزين المتراكم بيخبط فجأة (Caffeine Crash). وكمان شرب القهوة بعد العصر بيأخر النوم العميق حتى لو نمت.',
