    title: 'الإبهام عنده عضلاته المستقلة وأوتاره الفريدة اللي بنت الحضارة البشرية',
    body: 'قدرة إبهام الإنسان على التقابل الدقيق مع باقي الأصابع (Opposable Thumb) هي التي مكنتنا من الإمساك بالأقلام والأدوات الجراحية الدقيقة.',
    explanation: 'مساحة التحكم في القشرة الحركية بالمخ المخصصة للإبهام والأصابع والشفتين أكبر بكتير من المساحة المخصصة للظهر والرجل كلها!',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Thumb',
  ),
  Fact(
    id: 315,
    category: 'صحة وجسم الإنسان',
    title: 'النمش والشامات: الشمس بتشتغل كإنذار وحبر طبيعي في الجلد',
    body: 'عند التعرض للأشعة فوق البنفسجية، تفرز الخلايا الصبغية «الميلانين» ليلتف كالمظلة فوق نواة الخلية ويحمي الحمض النووي من التلف.',
    explanation: 'السمرة الصيفية مش علامة صحة زي ما بنفتكر، دي علامة إن الجلد بيحاول يدافع عن نفسه ضد الأشعة! فاستخدام واقي الشمس مهم لكل ألوان البشرة.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Melanin',
  ),
  Fact(
    id: 316,
    category: 'صحة وجسم الإنسان',
    title: 'الفيتامين الوحيد اللي جسمك بيصنعه من ضوء الشمس هو فيتامين د',
    body: 'عند تعرض الجلد لأشعة الشمس فوق البنفسجية (UVB)، يتحول مركب مشتق من الكوليسترول إلى فيتامين د الذي ينظم الكالسيوم والمناعة والمزاج.',
    explanation: 'الزجاج في الشبابيك والعربيات بيحجب أشعة UVB، فتعرض 10–15 دقيقة في الهوا الطلق (بعيدًا عن الحرق وقت الذروة) مفيد جدًا.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Vitamin_D',
  ),
  Fact(
