    title: 'العرق في حد ذاته مالوش ريحة تقريبًا: البكتيريا هي اللي بتعمل الريحة',
    body: 'العرق الطازج الخارج من الغدد العرقية يتكون أساسًا من الماء والأملاح وعديم الرائحة، لكن بكتيريا الجلد تفكك مركبات الغدد المفترزة فتنتج الرائحة.',
