    title: 'لماذا نحس بتشنج مفاجئ وإحساس بالسقوط وأنت داخل في النوم؟',
    body: 'الانتفاضة المفاجئة عند بداية النوم تُسمى «الرجفة النومية» (Hypnic Jerk)، وتحدث أثناء انتقال الجهاز العصبي من اليقظة إلى ارتخاء العضلات.',
    explanation: 'أحد التفسيرات إنها إشارة غير مكتملة بين إرخاء العضلات ومراقبة التوازن في المخ، وهي ظاهرة طبيعية تمامًا وبتزيد شوية مع التعب والكافيين.',
    sourceName: 'Wikipedia',
    url: 'https://en.wikipedia.org/wiki/Hypnic_jerk',
  ),
  Fact(
    id: 319,
    category: 'صحة وجسم الإنسان',
    title: 'ضغط عينك: ترميشة العين بتاخد عُشر ثانية وبتحصل ~15 ألف مرة يوميًا',
    body: 'يرمش الإنسان نحو 15–20 مرة في الدقيقة، وخلال كل رمشة يغسل الجفن سطح القرنية بالدموع ويمنع جفافها.',
    explanation: 'لما بتبص على شاشة الكمبيوتر أو الموبايل بتركيز، معدل الرمش بيقل للنص تقريبًا! قاعدة 20-20-20 (كل 20 دقيقة بص 20 قدم لمدة 20 ثانية) بتريح عينك جدًا.',
