    title: 'الدواء الوهمي (Placebo) بيشتغل أحيانًا حتى لو المريض عارف إنه دواء وهمي!',
    body: 'أظهرت تجارب سريرية أن تناول حبة خالية من المادة الفعالة مع اهتمام الطبيب وطقوس العلاج يحفّز الدماغ على إفراز مسكنات ألم طبيعية (إندورفينات).',
