    body: 'الأصوات التي يصدرها البطن (Borborygmi) ناتجة عن حركة عضلات الأمعاء التي تدفع الغازات والسوائل باستمرار، لكنها تُسمع أعلى عندما تكون المعدة فارغة كصدى صوتي.',
