    title: 'لماذا تشعر بالجوع بعد السهر الطويل؟ هرمون الجوع بيرتفع واللبتين بيقل',
    body: 'النوم أقل من 6 ساعات يرفع هرمون الجريلين (محفز الجوع) ويخفض هرمون اللبتين (هرمون الشبع)، فيدفعك الدماغ لاشتهاء السكريات والكربوهيدرات السريعة.',
