    title: 'فصيلة الدم O- هي «المعطي العام» لكرات الدم الحمراء، لكن في البلازما العكس!',
    body: 'لعدم وجود مستضدات A أو B أو Rh على كرات الدم الحمراء لفصيلة O السالب، يمكن نقلها لمعظم المرضى في الطوارئ؛ بينما في البلازما فصيلة AB هي المعطي العام.',
