    title: 'الإبرة والمخ: الإحساس بالحكة بيتنقل على نفس خط أعصاب الألم البطيء',
    body: 'تستجيب نهاية الأعصاب للهرش والألم الخفيف بإشارات متقاربة؛ وعندما تخدش جلدك، فإن الألم الخفيف اللحظي يشوّش مؤقتًا على إشارة الحكة في الحبل الشوكي.',
