    body: 'رغم أن قطرها أضيق من الأمعاء الغليظة، فإن الأمعاء الدقيقة مطوية بآلاف الخملات والخملات الدقيقة (Microvilli) لتزيد مساحة امتصاص الغذاء لعشرات الأمتار المربعة.',
